import{d as e,t}from"./index-CzbpWx4N.js";var n={dayNumber:2,weekNumber:1,cefrLevel:`a1`,dayBadge:`DAY 02 · 의도 vs 결과 반전`,categoryLabel:`일상·업무 근황 토크 핵심 시제`,title:`일찍 가려 했는데 결국 야근했어요`,subtitle:`원래 계획(meant to / was going to)과 예상 밖 결말(ended up -ing)을 한 호흡에 대조하는 법`,heroImage:`assets/scene_late_office.jpg`,secondaryImage:`assets/visual_preposition_card.jpg`,estimatedSprintMin:7,estimatedLectureMin:40,keyExpression:`I meant to ~, but I ended up -ing`,keySentenceByTier:{a1:`I wanted to leave early, but I worked late.`,a2:`I wanted to leave early, but I ended up working late.`,b1:`I meant to leave on time, but an urgent issue came up and I ended up staying late.`,b2:`I was originally planning to head out at six, only to get tied up with a client request and end up working past nine.`,c1:`Although I had every intention of wrapping up by six, a last-minute escalation cropped up and kept me at my desk until nine.`,c2:`Despite my best intentions to clock out promptly at six, an unforeseen client escalation derailed my evening and left me burning the midnight oil.`},youtubeVideo:e[2],readingPassage:{titleEn:`When Good Intentions Meet Last-Minute Requests`,titleKo:`정시 퇴근 계획이 갑작스러운 요청을 만났을 때`,genreBadge:`오피스 스토리 칼럼 · Lv.1–2`,estimatedMin:6,paragraphsEn:[`Every Tuesday morning, Chloe writes a clean to-do list and promises herself she will leave the office right at six. She even packs her running shoes so she can head straight to the gym after work.`,`Yesterday, however, everything went off script at 5:30 PM. A major client sent an urgent revision right before a regional launch, and two teammates were already stuck in traffic on their way to another meeting.`,`Chloe meant to answer just one quick email, but she ended up redesigning three slides and staying past eight. Before logging off, she left a polite note proposing an earlier review buffer so the whole team can avoid last-minute crunches next week.`],paragraphsSlash:[`Every Tuesday morning, / Chloe writes a clean to-do list / and promises herself / she will leave the office right at six. / She even packs her running shoes / so she can head straight to the gym after work.`,`Yesterday, however, / everything went off script at 5:30 PM. / A major client sent an urgent revision / right before a regional launch, / and two teammates were already stuck in traffic / on their way to another meeting.`,`Chloe meant to answer just one quick email, / but she ended up redesigning three slides / and staying past eight. / Before logging off, / she left a polite note proposing an earlier review buffer / so the whole team can avoid last-minute crunches next week.`],paragraphsKo:[`매주 화요일 아침, 클로이는 깔끔한 할 일 목록을 적으며 딱 6시에 퇴근하겠다고 다짐합니다. 퇴근하자마자 곧장 헬스장으로 갈 수 있도록 운동화까지 챙겨 오곤 합니다.`,`하지만 어제는 오후 5시 30분에 모든 계획이 어긋나고 말았습니다. 주요 고객사가 지역 론칭 직전에 긴급 수정 요청을 보냈고, 팀원 두 명은 이미 다른 미팅으로 이동하다 도로에 갇혀 있었기 때문입니다.`,`클로이는 짧은 이메일 하나만 답장하려 했지만, 결국 슬라이드 세 장을 다시 디자인하며 8시가 넘도록 야근하게 되었습니다. 퇴근 전 그녀는 다음 주에 막판 야근을 피할 수 있도록 사전 검수 여유 시간을 두자고 정중한 메모를 남겼습니다.`],keyExpressions:[`meant to ~`,`ended up -ing`,`went off script`,`stuck in traffic`,`last-minute revision`],comprehensionQuiz:[{id:`d2-rq01`,questionKo:`클로이가 어제 원래 오후 6시에 퇴근해서 하려던 계획은 무엇이었나요?`,options:[`친구와 저녁 식사를 하러 가기`,`운동화를 챙겨 곧장 헬스장에 가기`,`집에서 영화를 보며 쉬기`],answer:`운동화를 챙겨 곧장 헬스장에 가기`,explanationKo:`첫 문단 "packs her running shoes so she can head straight to the gym after work"에서 확인할 수 있습니다.`},{id:`d2-rq02`,questionKo:`클로이가 결국 8시 넘어서까지 야근하게 된 직접적인 원인은 무엇인가요?`,options:[`오후 5시 30분에 주요 고객사의 긴급 수정 요청이 들어왔기 때문`,`컴퓨터가 고장 나서 파일을 잃어버렸기 때문`,`팀 회식이 갑자기 잡혔기 때문`],answer:`오후 5시 30분에 주요 고객사의 긴급 수정 요청이 들어왔기 때문`,explanationKo:`둘째 문단 "A major client sent an urgent revision right before a regional launch"가 원인입니다.`},{id:`d2-rq03`,questionKo:`본문에서 "결국 ~하게 되었다"를 나타내는 올바른 문법 구조는?`,options:[`ended up to redesign`,`ended up redesigning`,`meant to redesigning`],answer:`ended up redesigning`,explanationKo:`end up 뒤에는 반드시 동명사(-ing)가 와야 합니다!`}]},vocabList:[{id:`d2-v01`,word:`meant to`,phonetic:`/ment tuː/`,pos:`핵심 구문`,meaningKo:`원래 ~하려고 했었다 (못 지킨 의도)`,meaningEn:`intended to do something, but failed to do it`,nuanceTipKo:`사과하거나 아쉬운 변명을 할 때 "I forgot"만 쓰기보다 "I meant to text you earlier(진작 연락하려 했는데)"라고 하면 훨씬 정중합니다.`,exampleEn:`Sorry! I meant to reply to your message this morning.`,exampleKo:`죄송해요! 오늘 아침에 답장드리려고 했었어요.`},{id:`d2-v02`,word:`end up -ing`,phonetic:`/end ʌp/`,pos:`구동사 구문`,meaningKo:`결국 (예상과 달리) ~하게 되다`,meaningEn:`finally be in a particular situation or do something unplanned`,nuanceTipKo:`뒤에 to부정사가 아니라 반드시 동명사(-ing)나 장소·명사구가 온다는 점이 시험과 회화 핵심입니다!`,exampleEn:`We missed the last train and ended up taking a taxi.`,exampleKo:`막차를 놓쳐서 결국 택시를 타게 됐어요.`},{id:`d2-v03`,word:`come up`,phonetic:`/kʌm ʌp/`,pos:`구동사`,meaningKo:`(예기치 않은 일·이슈가) 갑자기 생기다`,meaningEn:`happen unexpectedly`,nuanceTipKo:`약속을 못 지키거나 일정이 꼬였을 때 "Something urgent came up(급한 일이 생겼어요)"은 만능 구원투수 문장입니다.`,exampleEn:`An unexpected bug came up right before launch.`,exampleKo:`출시 직전에 예상치 못한 버그가 불거졌어요.`},{id:`d2-v04`,word:`work late`,phonetic:`/wɜːrk leɪt/`,pos:`연어(Collocation)`,meaningKo:`야근하다, 늦게까지 일하다`,meaningEn:`stay at work beyond regular hours`,nuanceTipKo:`한국어 "야근"을 night work(야간 교대근무)로 직역하면 오해가 생깁니다! 일반 직장인의 야근은 work late 또는 stay late at work입니다.`,exampleEn:`I had to work late three days in a row.`,exampleKo:`사흘 연속으로 야근해야 했어요.`},{id:`d2-v05`,word:`be swamped with`,phonetic:`/biː swɑːmpt wɪð/`,pos:`관용구`,meaningKo:`(업무 등에) 파묻혀 정신없이 바쁘다`,meaningEn:`be overwhelmed with too much work`,nuanceTipKo:`"I am very busy"만 반복하지 말고 "I've been swamped with work"를 쓰면 생생한 실무 영어가 됩니다.`,exampleEn:`I've been swamped with quarter-end reports all week.`,exampleKo:`일주일 내내 분기 마감 보고서에 파묻혀 지냈어요.`},{id:`d2-v06`,word:`be tied up with`,phonetic:`/biː taɪd ʌp wɪð/`,pos:`관용구`,meaningKo:`~에 발이 묶여 있다 (다른 일을 못 하는 상태)`,meaningEn:`be occupied with something so you cannot do anything else`,nuanceTipKo:`회의나 급한 건 때문에 전화를 못 받았을 때 정중하게 이유를 밝히기 아주 좋습니다.`,exampleEn:`Sorry I missed your call—I was tied up in a client meeting.`,exampleKo:`전화 못 받아서 죄송해요. 클라이언트 미팅에 묶여 있었어요.`},{id:`d2-v07`,word:`on time`,phonetic:`/ɑːn taɪm/`,pos:`전치사구`,meaningKo:`정각에, 제시간에 (정시 퇴근할 때도 사용)`,meaningEn:`at the scheduled or expected time`,nuanceTipKo:`"칼퇴하다"는 leave work right on time이라고 표현하면 정확합니다.`,exampleEn:`Hopefully, everyone can leave on time this Friday.`,exampleKo:`이번 금요일엔 다들 정시에 퇴근할 수 있으면 좋겠네요.`},{id:`d2-v08`,word:`in time`,phonetic:`/ɪn taɪm/`,pos:`전치사구`,meaningKo:`늦지 않게, 제때에 (마감·기차 출발 전 여유 있게)`,meaningEn:`early enough before a deadline or event`,nuanceTipKo:`on time은 정각 딱 맞춰, in time은 늦지 않게 아슬아슬/충분히 맞췄다는 뜻입니다.`,exampleEn:`We got to the gate just in time for boarding.`,exampleKo:`탑승 시간에 딱 늦지 않게 게이트에 도착했어요.`},{id:`d2-v09`,word:`was going to`,phonetic:`/wəz ˈɡoʊɪŋ tuː/`,pos:`조동사 구문`,meaningKo:`~하려고 했었는데 (계획 변경 암시)`,meaningEn:`planned to do something in the past`,nuanceTipKo:`과거진행 미래(was/were going to + 동사원형)는 회화에서 "원래 그러려고 했는데 못 했다"는 복선을 깔아줍니다.`,exampleEn:`I was going to cook at home, but I ordered delivery instead.`,exampleKo:`집에서 요리해 먹으려고 했는데 대신 배달을 시켰어요.`},{id:`d2-v10`,word:`at the last minute`,phonetic:`/æt ðə læst ˈmɪnɪt/`,pos:`전치사구`,meaningKo:`막판에, 마지막 순간에`,meaningEn:`just before it is too late or right before an event`,nuanceTipKo:`일정 취소나 수정 요청이 직전에 들어왔을 때 필수 부사구입니다.`,exampleEn:`The client changed the design specs at the last minute.`,exampleKo:`클라이언트가 막판에 디자인 사양을 바꿨어요.`},{id:`d2-v11`,word:`pull an all-nighter`,phonetic:`/pʊl ən ˈɔːlˌnaɪtər/`,pos:`관용구`,meaningKo:`(공부·업무로) 밤을 꼬박 새우다`,meaningEn:`stay awake all night working or studying`,nuanceTipKo:`대학생 시험 기간이나 직장인 마감 철야를 말할 때 가장 자연스러운 관용 표현입니다.`,exampleEn:`I’m too old to pull an all-nighter before presentations.`,exampleKo:`이제 발표 전에 밤을 꼬박 새우는 건 체력적으로 무리네요.`},{id:`d2-v12`,word:`lose track of time`,phonetic:`/luːz træk əv taɪm/`,pos:`관용구`,meaningKo:`시간 가는 줄 모르다`,meaningEn:`become unaware of what time it is because you are absorbed`,nuanceTipKo:`집중해서 일하거나 수다를 떨다가 시계를 보니 훌쩍 늦었을 때 씁니다.`,exampleEn:`We started chatting and completely lost track of time.`,exampleKo:`수다를 떨다 보니 시간 가는 줄 완전히 몰랐어요.`},{id:`d2-v13`,word:`burn the midnight oil`,phonetic:`/bɜːrn ðə ˈmɪdnaɪt ɔɪl/`,pos:`관용구`,meaningKo:`밤늦게까지 열심히 일하다/공부하다`,meaningEn:`work or study late into the night`,nuanceTipKo:`야근 중인 동료를 격려하거나 묘사할 때 재치 있게 쓸 수 있는 표현입니다.`,exampleEn:`Looks like the engineering team is burning the midnight oil again.`,exampleKo:`개발팀이 오늘도 밤늦게까지 불태우고 있나 보네요.`},{id:`d2-v14`,word:`make up for`,phonetic:`/meɪk ʌp fɔːr/`,pos:`구동사`,meaningKo:`(놓친 시간·실수를) 만회하다, 보상하다`,meaningEn:`compensate for something lost or missed`,nuanceTipKo:`야근이나 약속 취소 후 "주말에 푹 쉬며 보충해야지 / 다음번엔 내가 밥 살게" 할 때 유용합니다.`,exampleEn:`Let me buy you dinner next week to make up for canceling.`,exampleKo:`약속 취소한 거 만회할 겸 다음 주에 제가 저녁 살게요.`},{id:`d2-v15`,word:`a blessing in disguise`,phonetic:`/ə ˈblesɪŋ ɪn dɪsˈɡaɪz/`,pos:`관용구`,meaningKo:`전화위복 (처음엔 나빠 보였지만 결과적으로 다행인 일)`,meaningEn:`something that seems bad at first but turns out good`,nuanceTipKo:`예상 밖의 결과(end up)가 오히려 좋은 쪽으로 풀렸을 때 스토리를 멋지게 마무리해 줍니다.`,exampleEn:`Missing that flight turned out to be a blessing in disguise.`,exampleKo:`그 비행기를 놓친 게 결과적으로 전화위복이 되었어요.`}],dialogue:[{id:`d2-t1`,speaker:`Marcus`,roleLabel:`동료 디자이너`,voicePitch:.92,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`zoom-in`,english:`Chloe, are you still at your desk? I thought you were going to hit the gym at six!`,slashBroken:`Chloe, / are you still at your desk? / I thought / you were going to hit the gym at six!`,korean:`클로이, 아직도 자리에 있어? 6시에 헬스장 간다고 하지 않았어?`,keyHighlight:`were going to hit the gym`,noteKo:`hit the gym은 go to the gym보다 경쾌한 일상 회화 표현이며, were going to로 원래 계획을 짚어줍니다.`},{id:`d2-t2`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`pan-right`,english:`Tell me about it! I meant to leave right on time, but an urgent payment bug came up.`,slashBroken:`Tell me about it! / I meant to leave right on time, / but an urgent payment bug / came up.`,korean:`내 말이! 딱 정시에 퇴근하려고 했는데, 급한 결제 오류 건이 갑자기 터졌지 뭐야.`,keyHighlight:`meant to leave ~ came up`,noteKo:`"Tell me about it!"은 "내 말이 그 말이야!(완전 공감)"라는 감탄사입니다.`},{id:`d2-t3`,speaker:`Marcus`,roleLabel:`동료 디자이너`,voicePitch:.92,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`pan-left`,english:`Oh no, at the last minute? Did you manage to figure out what caused it?`,slashBroken:`Oh no, / at the last minute? / Did you manage to figure out / what caused it?`,korean:`저런, 퇴근 직전 막판에? 원인이 뭔지는 겨우 알아냈어?`,keyHighlight:`at the last minute`,noteKo:`manage to + 동사원형은 "쉽지 않았지만 가까스로 해내다"라는 뉘앙스를 더해줍니다.`},{id:`d2-t4`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`zoom-in`,english:`Thankfully, yes. Still, I ended up working two extra hours and missed my class.`,slashBroken:`Thankfully, yes. / Still, / I ended up working two extra hours / and missed my class.`,korean:`다행히 해결은 했어. 그래도 결국 두 시간이나 추가 야근을 하게 돼서 운동 수업은 놓쳤어.`,keyHighlight:`ended up working`,noteKo:`end up 뒤에는 반드시 동명사(-ing)를 연결하여 예상치 못한 최종 결말을 보여줍니다.`},{id:`d2-t5`,speaker:`Marcus`,roleLabel:`동료 디자이너`,voicePitch:.92,sceneImage:`assets/scene_cafe_detour.jpg`,cameraMotion:`pan-right`,english:`I've been swamped all day too. Actually, I was going to cook, but I'm way too tired.`,slashBroken:`I've been swamped all day too. / Actually, I was going to cook, / but I'm way too tired.`,korean:`나도 오늘 하루 종일 일에 파묻혀 있었어. 사실 집에서 요리하려 했는데 너무 지쳤네.`,keyHighlight:`I've been swamped`,noteKo:`하루 종일 지금까지 바쁜 상태가 이어졌으므로 현재완료(have been swamped)가 자연스럽습니다.`},{id:`d2-t6`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`zoom-in`,english:`Same here! Let's pack up now and grab some warm pho downstairs before heading home.`,slashBroken:`Same here! / Let's pack up now / and grab some warm pho downstairs / before heading home.`,korean:`나도! 이제 짐 챙겨서 퇴근하기 전에 아래층에서 따뜻한 쌀국수나 한 그릇 먹고 가자.`,keyHighlight:`Let's pack up`,noteKo:`pack up은 노트북과 가방을 챙겨 자리를 정리할 때 쓰는 실전 구동사입니다.`}],grammarSections:[{title:`원리 01 · 의도와 결과의 황금 공식: [I meant to V] + [but ended up V-ing]`,coreFormula:`I meant to + 동사원형 (원래 의도) , but I ended up + 동명사(-ing) (결말)`,wrongKonglish:`I intended leave early, but finally I worked night work.`,rightNative:`I meant to leave early, but I ended up working late.`,explanationKo:`일상 대화의 절반은 "원래 A하려 했는데 어쩌다 보니 B하게 됐다"는 스토리텔링입니다. 의도를 말할 땐 무거운 intended 대신 meant to 또는 was going to를 쓰고, 결말에는 부사 finally 대신 동사구 ended up -ing를 쓰면 원어민 특유의 리듬감 있는 반전 문장이 완성됩니다.`,registerSpectrum:{casual:`I was gonna sleep early, but I ended up binge-watching Netflix.`,standard:`I meant to leave on time, but I ended up working late.`,formal:`We originally planned to launch in May, but ended up postponing it to June.`}},{title:`원리 02 · 한국인이 가장 많이 틀리는 야근·업무량 콩글리시 교정`,coreFormula:`work late / stay late (야근하다) & a lot of work / swamped with work (많은 업무)`,wrongKonglish:`Because of many works, I did night work yesterday.`,rightNative:`I was swamped with work, so I had to work late yesterday.`,explanationKo:`① "업무"를 뜻하는 work는 셀 수 없는 불가산 명사이므로 many works라고 쓰면 큰 실수입니다(works는 공장/예술작품). ② night work는 밤낮이 바뀐 야간 교대근무를 뜻하므로, 직장인이 퇴근 시간을 넘겨 일하는 야근은 반드시 work late 또는 work overtime으로 표현하세요.`,registerSpectrum:{casual:`I had a ton of work, so I stayed late yesterday.`,standard:`I had a lot of work, so I ended up working late.`,formal:`Due to a heavy workload, I stayed past regular hours to finalize the report.`}},{title:`원리 03 · 핑계도 세련되게: 사람이 아닌 "상황(Something)"을 주어로 세우기`,coreFormula:`Something urgent came up. / An issue came up at the last minute.`,wrongKonglish:`Suddenly urgent thing happened to me, so I could not go.`,rightNative:`Something urgent came up at the last minute, so I couldn’t make it.`,explanationKo:`갑작스러운 사정을 설명할 때 happen보다 훨씬 자연스러운 구동사가 come up(불쑥 생기다/수면 위로 올라오다)입니다. 또한 형용사는 -thing 뒤에서 수식하므로 urgent something이 아니라 something urgent 어순이 되어야 합니다.`,registerSpectrum:{casual:`Sorry, something came up! Rain check?`,standard:`An urgent issue came up right before I left.`,formal:`Apologies, an unexpected client matter just came up on my end.`}}],sprintDrills:[{id:`d2-s01`,drillType:`chunk-build`,promptKo:`일찍 퇴근하려 했는데 결국 야근하게 됐어요.`,promptEnHint:`meant to + 동사원형, ended up + -ing 대조 구조를 조립하세요.`,targetEn:`I meant to leave early, but I ended up working late.`,chunks:[`I meant to`,`leave early,`,`but I ended up`,`working late.`],explanationKo:`의도(meant to leave)와 예상 밖 결과(ended up working)가 완벽한 대구를 이룹니다.`},{id:`d2-s02`,drillType:`active-blank`,promptKo:`막차를 놓쳐서 결국 택시를 타게 됐어요.`,promptEnHint:`ended up 뒤에 올 take의 알맞은 형태를 쓰세요.`,targetEn:`We missed the last train and ended up taking a taxi.`,blankData:{before:`We missed the last train and ended up`,answer:`taking`,after:`a taxi.`,firstLetterHint:`t_____ (-ing 형태)`},explanationKo:`end up 뒤에는 동명사(-ing)가 옵니다. e로 끝나는 동사 take는 e를 빼고 taking!`},{id:`d2-s03`,drillType:`konglish-fix`,promptKo:`"어제 일이 너무 많아서 야근했어요." — 바른 문장은?`,promptEnHint:`불가산 명사 work와 야근 표현을 점검하세요.`,targetEn:`I had a lot of work yesterday, so I worked late.`,wrongKonglishOption:`I had many works yesterday, so I did night work.`,explanationKo:`work는 불가산 명사(a lot of work)이며, 야근은 work late입니다.`},{id:`d2-s04`,drillType:`chunk-build`,promptKo:`오늘 아침에 답장드리려고 했었는데 깜빡했어요.`,promptEnHint:`아쉬운 의도 I meant to ~ 로 시작하세요.`,targetEn:`I meant to reply this morning, but it slipped my mind.`,chunks:[`I meant to`,`reply this morning,`,`but it`,`slipped my mind.`],explanationKo:`it slipped my mind는 I forgot보다 훨씬 부드럽고 세련된 표현입니다.`},{id:`d2-s05`,drillType:`active-blank`,promptKo:`퇴근 직전에 급한 일이 갑자기 생겼어요.`,promptEnHint:`이슈가 불거지다 구동사(과거형 2단어)를 넣으세요.`,targetEn:`Something urgent came up right before I left.`,blankData:{before:`Something urgent`,answer:`came up`,after:`right before I left.`,firstLetterHint:`c___ u_`},explanationKo:`예상치 못한 일이 생겼을 땐 come up의 과거형 came up을 씁니다.`},{id:`d2-s06`,drillType:`konglish-fix`,promptKo:`"이번 주 내내 업무에 파묻혀 정신없이 바빴어요."`,promptEnHint:`늪에 빠진 듯 바쁘다는 관용구를 고르세요.`,targetEn:`I've been swamped with work all week.`,wrongKonglishOption:`I've been drowned with many works all week.`,explanationKo:`be swamped with work가 실무에서 가장 널리 쓰이는 관용 표현입니다.`},{id:`d2-s07`,drillType:`chunk-build`,promptKo:`집에서 요리해 먹으려 했는데 대신 배달 음식을 시켰어요.`,promptEnHint:`과거 계획 I was going to ~ 로 시작하세요.`,targetEn:`I was going to cook at home, but I ordered delivery instead.`,chunks:[`I was going to`,`cook at home,`,`but I ordered`,`delivery instead.`],explanationKo:`was going to + 동사원형은 실행하지 못한 원래 계획을 자연스럽게 표현합니다.`},{id:`d2-s08`,drillType:`active-blank`,promptKo:`전화 못 받아서 죄송해요, 클라이언트 미팅에 묶여 있었어요.`,promptEnHint:`발이 묶여 바쁘다 be ____ up in 구문을 완성하세요.`,targetEn:`Sorry I missed your call—I was tied up in a client meeting.`,blankData:{before:`Sorry I missed your call—I was`,answer:`tied`,after:`up in a client meeting.`,firstLetterHint:`t___ (4글자)`},explanationKo:`be tied up in/with ~는 다른 용무를 볼 수 없을 만큼 붙잡혀 있을 때 씁니다.`},{id:`d2-s09`,drillType:`konglish-fix`,promptKo:`"수다를 떨다 보니 시간 가는 줄 완전히 몰랐어요."`,promptEnHint:`시간의 흐름을 놓치다는 관용구를 확인하세요.`,targetEn:`We started chatting and completely lost track of time.`,wrongKonglishOption:`We started chatting and completely forgot time going.`,explanationKo:`lose track of time(과거형 lost track of time)이 정확한 원어민 숙어입니다.`},{id:`d2-s10`,drillType:`chunk-build`,promptKo:`클라이언트가 막판에 디자인 요청사항을 바꿨어요.`,promptEnHint:`막판에 = at the last minute를 문미에 배치하세요.`,targetEn:`The client changed the design request at the last minute.`,chunks:[`The client`,`changed`,`the design request`,`at the last minute.`],explanationKo:`at the last minute는 일정·기획 변경 상황에서 매우 유용한 부사구입니다.`}],worksheetExam:[{id:`d2-ex01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`end up + 동명사`,questionKo:`괄호 안 동사 stay를 어법에 맞게 변형하여 "결국 밤 10시까지 회사에 남게 됐다"는 문장을 완성하세요.`,stimulusEn:`I meant to leave at six, but I ended up __________ (stay) until 10 PM.`,answer:`staying`,explanationKo:`end up 뒤에는 반드시 동명사(-ing)가 와야 하므로 staying이 정답입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 괄호 안 동사 pay를 알맞게 변형하여 빈칸을 채우세요.`,stimulusEn:`We lost the receipt and ended up __________ (pay) full price.`,answer:`paying`,explanationKo:`end up + 동명사 규칙에 따라 paying을 씁니다.`}},{id:`d2-ex02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`의도 표현 meant to`,questionKo:`빈칸에 알맞은 과거형 동사(1단어)를 넣어 "어제 전화드리려고 했었는데(못 드렸다)"는 문장을 완성하세요.`,stimulusEn:`I __________ to call you yesterday, but my phone battery died.`,answer:`meant`,explanationKo:`mean의 과거형 meant를 써서 지키지 못한 본래 의도(meant to + 동사원형)를 나타냅니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이 파일도 같이 첨부하려고 했었는데 깜빡했네요" 빈칸(1단어)을 채우세요.`,stimulusEn:`Oops, I __________ to attach the spreadsheet as well.`,answer:`meant`,explanationKo:`실수 후 정중히 의도를 밝힐 때 I meant to ~ 가 가장 자연스럽습니다.`}},{id:`d2-ex03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`돌발 이슈 come up`,questionKo:`빈칸에 알맞은 구동사(과거형 2단어)를 넣어 "가족에게 급한 일이 생겼다"는 문장을 완성하세요.`,stimulusEn:`I had to cancel my trip because a family emergency __________ __________.`,answer:`came up`,explanationKo:`예기치 않은 사건이나 급한 용무가 발생했을 때 come up(과거형 came up)을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "혹시 진행 중 문제가 생기면 바로 알려주세요" (현재시제 2단어)`,stimulusEn:`Please let me know right away if any issue __________ __________.`,answer:`comes up`,explanationKo:`단수 주어 any issue에 맞춰 3인칭 단수형 comes up을 씁니다.`}},{id:`d2-ex04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`업무 과부하 swamped`,questionKo:`빈칸에 알맞은 과거분사형 형용사(1단어)를 넣어 "신규 프로젝트로 정신없이 바쁘다"는 문장을 완성하세요.`,stimulusEn:`Sorry for the late response—I've been __________ with the new product launch.`,answer:`swamped`,acceptableAlt:[`tied`],explanationKo:`be swamped with ~는 업무에 파묻혀 눈코 뜰 새 없이 바쁜 상태를 나타냅니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "인터뷰 일정에 발이 묶여 있었다"가 되도록 빈칸(2단어)을 채우세요.`,stimulusEn:`I was __________ __________ in interviews all afternoon.`,answer:`tied up`,explanationKo:`be tied up in ~ 구문입니다.`}},{id:`d2-ex05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`시간 감각 관용구`,questionKo:`빈칸에 알맞은 명사(1단어)를 넣어 "코딩하다가 시간 가는 줄 몰랐다"는 문장을 완성하세요.`,stimulusEn:`I got so absorbed in coding that I completely lost __________ of time.`,answer:`track`,explanationKo:`lose track of time은 몰입하느라 시간 흐름을 놓쳤다는 필수 숙어입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "발표 준비로 밤을 꼬박 새웠다" 빈칸(1단어)을 채우세요.`,stimulusEn:`I had to __________ an all-nighter to finish the slides.`,answer:`pull`,explanationKo:`밤을 새우다는 pull an all-nighter 연어를 씁니다.`}},{id:`d2-ex06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`-thing 수식 어순`,questionKo:`다음 중 어법상 **올바른** 문장을 고르세요.`,stimulusEn:`상황: 급한 용무가 생겨 모임에 못 가게 되었음을 알리는 메시지`,options:[`Sorry, urgent something came up!`,`Sorry, something urgent came up!`,`Sorry, something urgently came up!`,`Sorry, an urgent came up!`],answer:`Sorry, something urgent came up!`,explanationKo:`something, anything, nothing처럼 -thing으로 끝나는 대명사는 형용사가 반드시 뒤에서 수식합니다(something urgent).`,twinClinic:{questionKo:`[쌍둥이 클리닉] "특별한 무언가"를 뜻하도록 (special / something)을 바른 순서(2단어)로 쓰세요.`,stimulusEn:`We prepared __________ __________ for your birthday.`,answer:`something special`,explanationKo:`대명사 something 뒤에 형용사 special이 옵니다.`}},{id:`d2-ex07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`on time vs in time 구별`,questionKo:`빈칸에 들어갈 전치사가 바르게 짝지어진 것을 고르세요.`,stimulusEn:`(A) Trains in Seoul almost always arrive right ____ time.
(B) Run! We need to get there ____ time to catch the opening scene.`,options:[`(A) on — (B) in`,`(A) in — (B) on`,`(A) at — (B) on`,`(A) on — (B) at`],answer:`(A) on — (B) in`,explanationKo:`시간표대로 정각에 도착하는 것은 on time, 어떤 일이 시작되기 전에 늦지 않게 도착하는 것은 in time (to V / for N)입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "정시에(칼같이 제시간에) 퇴근하다"가 되도록 전치사(1단어)를 넣으세요.`,stimulusEn:`I rarely get to leave work right __________ time on Mondays.`,answer:`on`,explanationKo:`정시 퇴근은 leave work on time입니다.`}},{id:`d2-ex08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`불가산 명사 work & 야근 표현`,questionKo:`직장인이 "요즘 일이 많아서 자주 야근해요"라고 말할 때 가장 자연스러운 문장은?`,stimulusEn:`콩글리시 함정(works, night work)을 피해서 선택하세요.`,options:[`I have many works these days, so I often do night work.`,`I have a heavy workload these days, so I often end up working late.`,`I have much works lately, so I work at night shift.`,`My works are too many, so I stay night.`],answer:`I have a heavy workload these days, so I often end up working late.`,explanationKo:`a heavy workload(또는 a lot of work)와 end up working late의 조합이 가장 격식 있고 자연스럽습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "사흘 연속 야근했다"에서 빈칸(2단어)을 채우세요.`,stimulusEn:`I had to __________ __________ three days in a row.`,answer:`work late`,explanationKo:`야근하다는 work late 또는 stay late로 표현합니다.`}},{id:`d2-ex09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`end up 문법 결합`,questionKo:`다음 중 밑줄 친 end up 뒤의 구조가 문법적으로 **어색한** 문장은?`,stimulusEn:`end up 뒤에 올 수 있는 형태(동명사, 전치사구, 형용사)를 점검하세요.`,options:[`We ended up ordering pizza at midnight.`,`He ended up to cancel the reservation.`,`How did we end up in the wrong terminal?`,`Everything ended up fine in the end.`],answer:`He ended up to cancel the reservation.`,explanationKo:`end up 뒤에는 동명사(canceling), 전치사구(in ~), 형용사(fine)는 올 수 있지만 to부정사(to cancel)는 올 수 없습니다!`,twinClinic:{questionKo:`[쌍둥이 클리닉] 위 틀린 문장의 "to cancel"을 어법에 맞는 1단어로 고치세요.`,stimulusEn:`He ended up __________ the reservation.`,answer:`canceling`,explanationKo:`동명사 canceling으로 고쳐야 합니다.`}},{id:`d2-ex10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`회화 맞장구 표현`,questionKo:`동료가 "이번 주 회의가 진짜 끝도 없이 많네!"라고 불평할 때 "내 말이 그 말이야!(완전 공감해)"라는 뜻의 대답은?`,stimulusEn:`Colleague: "We have way too many meetings this week!" → You: "____________________"`,options:[`Tell me about it!`,`Please explain it to me!`,`Say it again to me!`,`Let me tell you first!`],answer:`Tell me about it!`,explanationKo:`"Tell me about it!"은 직역("그것에 대해 말해줘")이 아니라 "안 그래도 내가 겪어봐서 너무 잘 알지, 내 말이!"라는 강한 공감 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 상대방 말에 "저도 마찬가지예요!"라고 짧게 2단어로 맞장구칠 때 쓰는 표현은?`,stimulusEn:`A: "I am way too tired to cook tonight." → B: "__________ __________!"`,answer:`Same here`,explanationKo:`"Same here!"는 Me too보다 어른스럽고 자연스러운 공감 표현입니다.`}},{id:`d2-ex11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`의도 vs 결과 통문장 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 완전한 영어 문장을 작성하세요.`,stimulusEn:`[ working late. / I meant to / on time, / but I ended up / leave ]`,answer:`I meant to leave on time, but I ended up working late.`,explanationKo:`[원래 의도] I meant to leave on time, + [반전 결과] but I ended up working late.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "커피만 한 잔 마시려 했는데 결국 두 시간 동안 수다를 떨었어요." (I meant to / just grab a coffee, / but we ended up / chatting for two hours.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I meant to just grab a coffee, but we ended up chatting for two hours.`,explanationKo:`ended up + 동명사 chatting 구조를 정확히 적용합니다.`}},{id:`d2-ex12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`was going to + instead 결합`,questionKo:`주어진 청크를 배열하여 "원래 헬스장에 가려 했는데 대신 집에 일찍 갔다"는 문장을 완성하세요.`,stimulusEn:`[ hit the gym, / instead. / I was going to / went straight home / but I ]`,answer:`I was going to hit the gym, but I went straight home instead.`,explanationKo:`대안 행동을 선택한 뒤 문장 맨 끝에 부사 instead를 붙이면 대비가 아주 선명해집니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "지하철을 타려 했는데 대신 버스를 탔어요." (I was going to / take the subway, / but I took the bus / instead.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I was going to take the subway, but I took the bus instead.`,explanationKo:`was going to V, but + 과거동사 + instead 패턴입니다.`}},{id:`d2-ex13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`비즈니스 부재 사과문`,questionKo:`우리말 뜻에 맞게 주어진 표현을 활용하여 정중한 비즈니스 사과 문장을 완성하세요.`,stimulusEn:`우리말: 전화 못 받아서 죄송해요. 클라이언트 미팅에 묶여 있었어요.
(힌트: Sorry I missed your call, / I was tied up in / a client meeting.)`,answer:`Sorry I missed your call, I was tied up in a client meeting.`,acceptableAlt:[`Sorry I missed your call—I was tied up in a client meeting.`,`Sorry I missed your call. I was tied up in a client meeting.`],explanationKo:`missed your call과 was tied up in ~ 의 결합은 실무 전화·슬랙 메시지의 정석입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "답장이 늦어 죄송해요, 오늘 하루 종일 업무에 파묻혀 있었어요." (Sorry for the late reply, / I was swamped with work / all day.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Sorry for the late reply, I was swamped with work all day.`,explanationKo:`Sorry for the late reply + I was swamped with work all day.`}},{id:`d2-ex14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장의 오류 2곳을 바르게 고쳐 완전한 문장으로 다시 쓰세요.`,stimulusEn:`오류 문장: Urgent something came up, so I ended up to stay late.`,answer:`Something urgent came up, so I ended up staying late.`,explanationKo:`① Urgent something → Something urgent (후치 수식), ② ended up to stay → ended up staying (동명사 목적어).`,twinClinic:{questionKo:`[쌍둥이 클리닉] 다음 오류 문장을 바르게 고쳐 쓰세요: I had many works, so I ended up to miss dinner.`,stimulusEn:`오류 2곳(many works, to miss)을 교정하세요.`,answer:`I had a lot of work, so I ended up missing dinner.`,explanationKo:`불가산 명사 a lot of work와 동명사 missing으로 고칩니다.`}},{id:`d2-ex15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`만회 제안 영작`,questionKo:`다음 우리말을 make up for를 활용하여 영작하세요.`,stimulusEn:`우리말: 약속 취소한 것을 만회하기 위해 다음 주에 제가 저녁 살게요.
(힌트: Let me buy you dinner / next week / to make up for / canceling.)`,answer:`Let me buy you dinner next week to make up for canceling.`,explanationKo:`전치사 for 뒤에는 동명사 canceling이 오며, Let me buy you ~ 는 기분 좋게 대접하겠다는 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "늦은 것을 만회하기 위해 제가 커피 살게요." (Let me grab you a coffee / to make up for / being late.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let me grab you a coffee to make up for being late.`,explanationKo:`전치사 for 뒤에 동명사구 being late를 연결합니다.`}}],tutorScenario:{openingQuestionEn:`Think about your past week—was there a day when you meant to finish early or relax, but something came up and changed your plans?`,openingQuestionKo:`지난 한 주를 떠올려 볼까요? 일찍 끝내거나 쉬려고 했는데, 갑자기 일이 생겨 계획이 바뀐 날이 있었나요?`,followUpQuestionEn:`How did you end up spending that evening instead, and how are you going to make up for that lost rest this weekend?`,followUpQuestionKo:`결국 그날 저녁을 어떻게 보내게 되셨나요? 그리고 이번 주말엔 놓친 휴식을 어떻게 보충하실 계획인가요?`,recommendedChunks:[`I meant to ~`,`something came up`,`ended up -ing`,`swamped with work`,`make up for ~`],modelAnswerEn:`On Wednesday, I meant to leave on time and watch a movie, but an urgent report came up and I ended up working until nine. I plan to sleep in this Saturday to make up for it!`}},r={dayNumber:3,weekNumber:1,cefrLevel:`a2`,dayBadge:`DAY 03 · 완곡한 거절 & 일정 조율`,categoryLabel:`비즈니스 & 실전 커뮤니케이션 매너`,title:`내일은 일정이 좀 애매하네요`,subtitle:`직설적인 No 없이 상대의 기분을 배려하며 프로답게 시간을 미루고 역제안하는 기술`,heroImage:`assets/office_sitcom_scene.jpg`,secondaryImage:`assets/scene_video_call.jpg`,estimatedSprintMin:7,estimatedLectureMin:42,keyExpression:`Tomorrow looks a bit tight — would ~ work instead?`,keySentenceByTier:{a1:`Tomorrow is busy for me. Can we meet on Thursday?`,a2:`Tomorrow is a bit tight for me. Can we do Thursday instead?`,b1:`Tomorrow looks a bit tight on my end. Would Thursday afternoon work instead?`,b2:`My calendar is pretty packed tomorrow—could we possibly push our sync back to Thursday at 2 PM instead?`,c1:`Given back-to-back client reviews tomorrow, I am quite stretched; would pushing our sync to Thursday afternoon work on your end?`,c2:`With back-to-back deliverables crowding tomorrow’s calendar, I’d hate to shortchange our discussion—might we move our sync to Thursday afternoon instead?`},youtubeVideo:e[3],readingPassage:{titleEn:`How to Say No to a Meeting Without Burning Bridges`,titleKo:`관계를 해치지 않으면서 회의 일정을 정중히 미루는 법`,genreBadge:`비즈니스 매너 가이드 · Lv.2`,estimatedMin:6,paragraphsEn:[`Many Korean professionals hesitate to decline a meeting request because a direct "I cannot make it" sounds harsh. In English workplace culture, however, politely rescheduling is seen as a sign of reliability rather than rudeness.`,`The golden formula has two simple parts: first, briefly acknowledge the invite and note that your schedule looks tight; second, immediately offer one or two concrete alternative slots. Saying "Tomorrow looks tight on my end—would Thursday at 2 PM work instead?" keeps the conversation moving smoothly.`,`Avoid vague Konglish phrases like "Tomorrow is ambiguous" or "I have another promise." Native colleagues respond much better to specific availability words such as packed, tied up, or wide open.`],paragraphsSlash:[`Many Korean professionals hesitate / to decline a meeting request / because a direct "I cannot make it" sounds harsh. / In English workplace culture, however, / politely rescheduling is seen as a sign of reliability / rather than rudeness.`,`The golden formula has two simple parts: / first, briefly acknowledge the invite / and note that your schedule looks tight; / second, immediately offer one or two concrete alternative slots. / Saying "Tomorrow looks tight on my end—would Thursday at 2 PM work instead?" / keeps the conversation moving smoothly.`,`Avoid vague Konglish phrases / like "Tomorrow is ambiguous" or "I have another promise." / Native colleagues respond much better / to specific availability words / such as packed, tied up, or wide open.`],paragraphsKo:[`많은 한국 직장인이 “참석 못 해요”라는 직설적인 표현이 무례하게 들릴까 봐 회의 일정 거절을 망설입니다. 하지만 영어권 직장 문화에서는 정중하게 일정을 재조율하는 것이 무례함이 아니라 신뢰감의 신호로 받아들여집니다.`,`황금 공식은 두 가지 단순한 요소로 이루어집니다. 첫째, 초대에 감사를 표하고 일정이 빠듯하다고 짧게 알립니다. 둘째, 즉시 구체적인 대안 시간 1~2개를 제시합니다. “내일은 제 쪽 일정이 빠듯하네요—대신 목요일 오후 2시가 괜찮으실까요?”라고 말하면 대화가 매끄럽게 이어집니다.`,`“내일은 애매해요(ambiguous)”나 “약속(promise)이 있어요” 같은 모호한 콩글리시는 피하세요. 원어민 동료들은 packed(꽉 찬), tied up(묶여 있는), wide open(여유 있는)처럼 명확한 일정 표현에 훨씬 긍정적으로 반응합니다.`],keyExpressions:[`looks tight on my end`,`would ~ work instead?`,`alternative slots`,`packed`,`tied up`],comprehensionQuiz:[{id:`d3-rq01`,questionKo:`영어권 직장 문화에서 정중하게 일정을 재조율하는 것은 어떻게 인식되나요?`,options:[`업무 의욕이 부족하다는 신호`,`무례함이 아니라 신뢰감(reliability)의 신호`,`상대방과의 관계를 끊겠다는 의미`],answer:`무례함이 아니라 신뢰감(reliability)의 신호`,explanationKo:`첫 문단 "politely rescheduling is seen as a sign of reliability rather than rudeness"가 핵심입니다.`},{id:`d3-rq02`,questionKo:`일정 거절의 황금 공식 2단계 중 두 번째 단계는 무엇인가요?`,options:[`구체적인 대안 시간 1~2개를 즉시 역제안한다`,`일정이 비어 있을 때 나중에 연락하겠다고만 말한다`,`왜 바쁜지 개인 사정을 5문장 이상 상세히 설명한다`],answer:`구체적인 대안 시간 1~2개를 즉시 역제안한다`,explanationKo:`둘째 문단 "immediately offer one or two concrete alternative slots"를 확인하세요.`},{id:`d3-rq03`,questionKo:`다음 중 본문이 피하라고 조언한 콩글리시 표현은?`,options:[`My calendar is packed tomorrow.`,`Tomorrow is ambiguous.`,`Thursday afternoon is wide open.`],answer:`Tomorrow is ambiguous.`,explanationKo:`ambiguous는 뜻이 모호하다는 의미이며, 일정이 빠듯할 때는 tight/packed를 씁니다.`}]},vocabList:[{id:`d3-v01`,word:`tight`,phonetic:`/taɪt/`,pos:`형용사`,meaningKo:`(일정·예산이) 빠듯한, 여유가 없는 ("애매한")`,meaningEn:`having very little free time or room to spare`,nuanceTipKo:`한국어 "내일 일정이 좀 애매해요"를 ambiguous(뜻이 모호한)로 직역하면 콩글리시입니다! 일정이 빠듯할 땐 tight나 tricky가 정답입니다.`,exampleEn:`This week is a bit tight, so let’s aim for next Monday.`,exampleKo:`이번 주는 일정이 좀 빠듯해서 다음 주 월요일로 잡아보죠.`},{id:`d3-v02`,word:`on my end`,phonetic:`/ɑːn maɪ end/`,pos:`전치사구`,meaningKo:`제 쪽(상황/입장)에서는`,meaningEn:`from my side or perspective in a shared arrangement`,nuanceTipKo:`거절이나 상황 설명 끝에 on my end를 붙이면 단정적인 느낌을 덜어내고 훨씬 프로페셔널해집니다.`,exampleEn:`Everything looks good on my end—ready whenever you are.`,exampleKo:`제 쪽에서는 다 문제없습니다. 준비되실 때 시작하시죠.`},{id:`d3-v03`,word:`push ~ back`,phonetic:`/pʊʃ bæk/`,pos:`구동사`,meaningKo:`(일정·회의 시간을) 뒤로 미루다, 늦추다`,meaningEn:`move a scheduled time to a later time or date`,nuanceTipKo:`delay는 열차 연착 같은 부정적 지연 느낌이 강합니다. 상호 합의로 회의를 늦출 때는 push ~ back이나 reschedule을 쓰세요.`,exampleEn:`Could we push our call back by 30 minutes?`,exampleKo:`통화 시간을 30분만 뒤로 미뤄도 될까요?`},{id:`d3-v04`,word:`move ~ up`,phonetic:`/muːv ʌp/`,pos:`구동사`,meaningKo:`(일정을) 앞당기다`,meaningEn:`change a scheduled event to an earlier time`,nuanceTipKo:`push back(뒤로 미루다)의 반대말! 달력 위쪽(이른 날짜/시간)으로 끌어올린다는 그림으로 이해하세요.`,exampleEn:`Can we move the meeting up to Tuesday morning?`,exampleKo:`회의를 화요일 오전으로 앞당길 수 있을까요?`},{id:`d3-v05`,word:`work for someone`,phonetic:`/wɜːrk fɔːr/`,pos:`동사 구문`,meaningKo:`(시간·장소·조건이 ~에게) 괜찮다, 맞다`,meaningEn:`be convenient or acceptable for someone`,nuanceTipKo:`"Is 3 PM possible?"보다 "Does 3 PM work for you?"가 10배 더 원어민답고 자연스럽습니다.`,exampleEn:`Does Thursday at 2 PM work for everyone?`,exampleKo:`목요일 오후 2시 다들 시간 괜찮으신가요?`},{id:`d3-v06`,word:`have plans`,phonetic:`/hæv plænz/`,pos:`연어(Collocation)`,meaningKo:`(선약·만남) 약속이 있다`,meaningEn:`already have an arrangement to meet someone or do something`,nuanceTipKo:`친구와 약속 있다고 할 때 have a promise(맹세/서약)를 쓰면 절대 안 됩니다! 복수형 have plans를 외워두세요.`,exampleEn:`I already have dinner plans with an old friend tonight.`,exampleKo:`오늘 저녁엔 오랜 친구와 이미 저녁 약속이 있어요.`},{id:`d3-v07`,word:`a prior commitment`,phonetic:`/ə ˈpraɪər kəˈmɪtmənt/`,pos:`명사구`,meaningKo:`선약 (격식 있는 비즈니스 표현)`,meaningEn:`an existing engagement or responsibility made earlier`,nuanceTipKo:`구체적인 사생활을 밝히지 않고도 정중하게 회식이나 미팅 초대를 거절하는 고급 비즈니스 치트키입니다.`,exampleEn:`Unfortunately, I have a prior commitment that evening.`,exampleKo:`아쉽게도 그날 저녁에는 선약이 있습니다.`},{id:`d3-v08`,word:`take a rain check`,phonetic:`/teɪk ə reɪn tʃek/`,pos:`관용구`,meaningKo:`(아쉽지만) 다음을 기약하다, 다음에 꼭 함께하다`,meaningEn:`politely decline an invitation now with the hope of accepting later`,nuanceTipKo:`우천 취소 야구표(rain check)에서 유래한 표현! 식사·커피 제안을 기분 좋게 다음으로 미룰 때 최고입니다.`,exampleEn:`I'm swamped today—can I take a rain check on lunch?`,exampleKo:`오늘은 너무 바빠서 그런데 점심은 다음을 기약해도 될까요?`},{id:`d3-v09`,word:`pencil in`,phonetic:`/ˈpensl ɪn/`,pos:`구동사`,meaningKo:`가계약(임시 일정)으로 일단 잡아두다`,meaningEn:`arrange something tentatively, knowing it might change`,nuanceTipKo:`볼펜이 아닌 연필(pencil)로 적는다는 뜻에서 "일단 가볍게 시간 비워두자"는 뉘앙스를 정확히 전달합니다.`,exampleEn:`Let's pencil in Friday at 11 AM and confirm on Thursday.`,exampleKo:`일단 금요일 11시로 가일정을 잡아두고 목요일에 확정하죠.`},{id:`d3-v10`,word:`back-to-back`,phonetic:`/ˌbæk tə ˈbæk/`,pos:`형용사/부사`,meaningKo:`쉬는 틈 없이 연달아 이어지는`,meaningEn:`happening one right after another without a break`,nuanceTipKo:`연속 회의가 잡혀 있어 짬이 안 날 때 "I have back-to-back meetings"라고 쓰면 단번에 상황이 설명됩니다.`,exampleEn:`I'm in back-to-back meetings from 1 to 5 PM.`,exampleKo:`오후 1시부터 5시까지 연달아 회의가 잡혀 있어요.`},{id:`d3-v11`,word:`reschedule`,phonetic:`/ˌriːˈskedʒuːl/`,pos:`동사`,meaningKo:`일정을 다시 잡다(변경하다)`,meaningEn:`change the time of a planned event`,nuanceTipKo:`change the time보다 깔끔하며, 전치사 for와 결합해 reschedule ~ for Friday처럼 새 날짜를 제시합니다.`,exampleEn:`Would it be okay if we rescheduled our 1-on-1 for Friday?`,exampleKo:`우리 1:1 미팅을 금요일로 다시 잡아도 괜찮을까요?`},{id:`d3-v12`,word:`make it`,phonetic:`/meɪk ɪt/`,pos:`관용구`,meaningKo:`(모임·약속 시간에 맞춰) 참석하다, 오다`,meaningEn:`be able to attend an event or arrive in time`,nuanceTipKo:`"Can you come?" 대신 "Can you make it?"을, 못 갈 때는 "I can't make it"을 쓰면 훨씬 부드럽습니다.`,exampleEn:`I'm afraid I won't be able to make it to the workshop.`,exampleKo:`아쉽게도 워크숍에는 참석하기 어려울 것 같습니다.`},{id:`d3-v13`,word:`wide open`,phonetic:`/waɪd ˈoʊpən/`,pos:`형용사구`,meaningKo:`(특정 요일·시간대 일정이) 텅 비어 여유로운`,meaningEn:`completely free with no scheduled events`,nuanceTipKo:`"아무 때나 다 돼요!"라고 말할 때 "My Friday afternoon is wide open"이라고 하면 명확합니다.`,exampleEn:`My afternoon is wide open after 2 PM.`,exampleKo:`오후 2시 이후로는 일정이 완전히 비어 있어요.`},{id:`d3-v14`,word:`squeeze ~ in`,phonetic:`/skwiːz ɪn/`,pos:`구동사`,meaningKo:`(빡빡한 일정 틈새에) 짬을 내어 끼워 넣다`,meaningEn:`manage to find a short slot for someone or something`,nuanceTipKo:`바쁜 와중에도 상대를 배려해 15분 정도 시간을 내줄 때 쓰는 고마운 표현입니다.`,exampleEn:`I can squeeze in a quick 15-minute call before noon.`,exampleKo:`정오 전에 15분 정도 짧게 통화할 짬은 낼 수 있어요.`},{id:`d3-v15`,word:`lock in`,phonetic:`/lɑːk ɪn/`,pos:`구동사`,meaningKo:`(시간·계획·조건을) 최종 확정 짓다`,meaningEn:`finalize and commit to a time or plan`,nuanceTipKo:`pencil in(가일정)과 대조되는 표현으로, 캘린더 초대를 보내며 최종 확정할 때 자주 씁니다.`,exampleEn:`Great, let's lock in Thursday at 3 PM—I'll send the invite.`,exampleKo:`좋습니다, 목요일 오후 3시로 확정하죠. 캘린더 초대장 보낼게요.`}],dialogue:[{id:`d3-t1`,speaker:`Marcus`,roleLabel:`프로덕트 디자이너`,voicePitch:.92,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Hey Chloe, do you have half an hour tomorrow morning to review the Q3 roadmap?`,slashBroken:`Hey Chloe, / do you have half an hour / tomorrow morning / to review the Q3 roadmap?`,korean:`클로이, 내일 오전에 3분기 로드맵 같이 검토할 시간 30분 정도 괜찮아?`,keyHighlight:`half an hour tomorrow morning`,noteKo:`30 minutes 대신 일상 대화에서는 half an hour도 매우 자주 쓰입니다.`},{id:`d3-t2`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`Let me check my calendar... Oh, tomorrow morning looks pretty tight on my end.`,slashBroken:`Let me check my calendar... / Oh, tomorrow morning looks / pretty tight / on my end.`,korean:`캘린더 좀 확인해 볼게... 아, 내일 오전은 내 쪽 일정이 꽤 빠듯하네(애매하네).`,keyHighlight:`looks pretty tight on my end`,noteKo:`바로 "No, I can't"라고 자르지 않고 "looks pretty tight on my end"로 쿠션을 깔아줍니다.`},{id:`d3-t3`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`I'm in back-to-back interviews until noon. Could we push it back to Thursday instead?`,slashBroken:`I'm in back-to-back interviews until noon. / Could we push it back / to Thursday instead?`,korean:`정오까지 면접이 연달아 잡혀 있거든. 대신 목요일로 좀 미뤄도 될까?`,keyHighlight:`push it back to Thursday instead`,noteKo:`[짧은 이유 설명] + [대안 역제안(instead)]은 비즈니스 거절의 완벽한 2단 콤보입니다.`},{id:`d3-t4`,speaker:`Marcus`,roleLabel:`프로덕트 디자이너`,voicePitch:.92,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`No problem at all! My Thursday afternoon is wide open after 2 PM. What time works best for you?`,slashBroken:`No problem at all! / My Thursday afternoon is wide open / after 2 PM. / What time works best for you?`,korean:`전혀 문제없어! 난 목요일 오후 2시 이후로는 일정이 텅 비어 있어. 몇 시가 제일 편해?`,keyHighlight:`What time works best for you?`,noteKo:`상대에게 가장 편한 시간을 물어볼 때 "What time works best for you?"를 통째로 외워 쓰세요.`},{id:`d3-t5`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`How does 2:30 PM sound? That gives me enough time to look over your mockups beforehand.`,slashBroken:`How does 2:30 PM sound? / That gives me enough time / to look over your mockups beforehand.`,korean:`오후 2시 반 어때? 그래야 미팅 전에 네 시안을 미리 살펴볼 시간이 충분할 것 같아.`,keyHighlight:`How does 2:30 PM sound?`,noteKo:`"How does [시간/제안] sound?"는 부드럽게 의견을 묻는 세련된 표현입니다.`},{id:`d3-t6`,speaker:`Marcus`,roleLabel:`프로덕트 디자이너`,voicePitch:.92,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`2:30 works great! Let's lock it in—I'll send over a calendar invite right now.`,slashBroken:`2:30 works great! / Let's lock it in— / I'll send over a calendar invite right now.`,korean:`2시 반 아주 좋아! 그렇게 확정하자. 지금 바로 캘린더 초대장 보낼게.`,keyHighlight:`Let's lock it in`,noteKo:`대명사 it을 구동사 가운데 넣어 lock it in으로 확정하고 캘린더 초대(calendar invite)로 마무리합니다.`}],grammarSections:[{title:`원리 01 · 프로의 3단 완곡 거절 공식: [완충 쿠션] + [짧은 사유] + [대안 역제안]`,coreFormula:`[시간] looks a bit tight on my end + (사유) + Would [새 시간] work instead?`,wrongKonglish:`Tomorrow is impossible because my schedule is ambiguous. Please delay it.`,rightNative:`Tomorrow looks a bit tight on my end. Would Thursday afternoon work instead?`,explanationKo:`영어권 실무에서 "impossible"이나 "cannot"만 툭 던지면 협업 의지가 없는 것처럼 들릴 수 있습니다. ① 내 일정이 빠듯하다는 쿠션(looks a bit tight on my end)을 깔고, ② 대안 시간 뒤에 instead를 붙여 "Would ~ work instead?"라고 역제안하면 거절이 아니라 매끄러운 조율이 됩니다.`,registerSpectrum:{casual:`Tomorrow is kinda crazy for me—can we do Thursday instead?`,standard:`Tomorrow looks a bit tight on my end. Would Thursday afternoon work instead?`,formal:`Unfortunately, I have a prior commitment tomorrow. Might Friday morning work for you instead?`}},{title:`원리 02 · 한국어 "약속"의 두 얼굴: have plans vs. make a promise`,coreFormula:`have plans (만남·일정 약속이 있다) / a prior commitment (비즈니스 선약)`,wrongKonglish:`Sorry, I have a promise with my friend tonight.`,rightNative:`Sorry, I already have plans with a friend tonight.`,explanationKo:`한국어에서는 "새끼손가락 걸고 한 맹세"도 약속, "저녁 7시에 강남역에서 밥 먹기로 한 일정"도 약속이라고 부릅니다. 하지만 영어에서 promise는 전자(맹세·보증)만을 뜻합니다! 누군가와 만나기로 한 선약은 반드시 복수형 명사 plans(I have plans) 또는 격식체 a prior commitment를 써야 합니다.`,registerSpectrum:{casual:`Ah, I've got dinner plans tonight. Rain check?`,standard:`I already have plans with a friend this evening.`,formal:`I regret that I have a prior commitment this evening.`}},{title:`원리 03 · 캘린더 이동 방향 감각: 앞당기면 move up, 늦추면 push back`,coreFormula:`move [일정] up to [이른 시점] ↔ push [일정] back to [늦은 시점]`,wrongKonglish:`Can we pull the meeting early or delay it to 4 PM?`,rightNative:`Can we move the meeting up to 1 PM, or push it back to 4 PM?`,explanationKo:`종이 달력이나 구글 캘린더 화면을 떠올려 보세요! 위쪽이 오전(이른 날짜), 아래쪽이 오후(나중 날짜)입니다. 그래서 시간을 앞당길 때는 위로 올리는 move ~ up을 쓰고, 뒤로 늦출 때는 뒤로 미는 push ~ back을 씁니다. 목적어가 it이면 반드시 move it up / push it back 어순을 지키세요.`,registerSpectrum:{casual:`Mind if we push lunch back by 30 minutes?`,standard:`Could we push our sync back to 4 PM?`,formal:`Would it be possible to reschedule our session for next Tuesday?`}}],sprintDrills:[{id:`d3-s01`,drillType:`chunk-build`,promptKo:`내일은 제 쪽 일정이 좀 빠듯해(애매해) 보이네요.`,promptEnHint:`looks a bit tight + on my end 조합을 만드세요.`,targetEn:`Tomorrow looks a bit tight on my end.`,chunks:[`Tomorrow`,`looks`,`a bit tight`,`on my end.`],explanationKo:`ambiguous 대신 tight를 쓰고 on my end로 부드럽게 마무리합니다.`},{id:`d3-s02`,drillType:`konglish-fix`,promptKo:`"오늘 저녁에 친구랑 이미 약속이 있어요."`,promptEnHint:`만남 약속은 promise가 아닙니다!`,targetEn:`I already have plans with a friend tonight.`,wrongKonglishOption:`I already have a promise with a friend tonight.`,explanationKo:`일상적인 만남 약속은 복수형 명사 plans(have plans)를 사용합니다.`},{id:`d3-s03`,drillType:`chunk-build`,promptKo:`대신 목요일 오후는 시간 괜찮으실까요?`,promptEnHint:`Would ~ work instead? 패턴으로 역제안하세요.`,targetEn:`Would Thursday afternoon work instead?`,chunks:[`Would`,`Thursday afternoon`,`work`,`instead?`],explanationKo:`동사 work("시간이 맞다/괜찮다")를 활용한 최고의 역제안 문장입니다.`},{id:`d3-s04`,drillType:`active-blank`,promptKo:`우리 통화를 30분만 뒤로 미뤄도 될까요?`,promptEnHint:`push our call ____ (뒤로 미루다)에 알맞은 부사를 넣으세요.`,targetEn:`Could we push our call back by 30 minutes?`,blankData:{before:`Could we push our call`,answer:`back`,after:`by 30 minutes?`,firstLetterHint:`b___ (4글자)`},explanationKo:`일정을 늦출 때는 push ~ back 구동사를 쓰고 시간 차이 앞에는 전치사 by를 붙입니다.`},{id:`d3-s05`,drillType:`active-blank`,promptKo:`회의를 화요일 오전으로 앞당길 수 있을까요?`,promptEnHint:`달력 위쪽으로 당기다 move the meeting __ (부사 1단어)`,targetEn:`Can we move the meeting up to Tuesday morning?`,blankData:{before:`Can we move the meeting`,answer:`up`,after:`to Tuesday morning?`,firstLetterHint:`u_ (2글자)`},explanationKo:`일정을 앞당길 때는 move ~ up을 씁니다.`},{id:`d3-s06`,drillType:`konglish-fix`,promptKo:`"오후 1시부터 5시까지 연달아(빈틈없이) 회의가 있어요."`,promptEnHint:`연속 회의를 뜻하는 원어민 형용사를 고르세요.`,targetEn:`I have back-to-back meetings from 1 to 5 PM.`,wrongKonglishOption:`I have relay nonstop meetings from 1 to 5 PM.`,explanationKo:`쉬는 시간 없이 연이어 잡힌 회의는 back-to-back meetings라고 표현합니다.`},{id:`d3-s07`,drillType:`chunk-build`,promptKo:`오늘은 너무 바쁜데 점심은 다음을 기약해도 될까요?`,promptEnHint:`우천 교환권 관용구 take a rain check를 조립하세요.`,targetEn:`Can I take a rain check on lunch today?`,chunks:[`Can I`,`take a rain check`,`on lunch`,`today?`],explanationKo:`상대의 호의를 고맙게 받으면서 다음 기회로 미루는 가장 기분 좋은 표현입니다.`},{id:`d3-s08`,drillType:`active-blank`,promptKo:`아쉽게도 그날 저녁에는 선약이 있습니다. (비즈니스 격식)`,promptEnHint:`prior와 짝을 이루는 격식 명사(c로 시작)를 쓰세요.`,targetEn:`Unfortunately, I have a prior commitment that evening.`,blankData:{before:`Unfortunately, I have a prior`,answer:`commitment`,after:`that evening.`,firstLetterHint:`c_________ (10글자)`},explanationKo:`a prior commitment는 사적인 사유를 구구절절 설명하지 않고도 품위 있게 거절하는 표현입니다.`},{id:`d3-s09`,drillType:`chunk-build`,promptKo:`일단 금요일 11시로 가일정을 잡아두죠.`,promptEnHint:`연필로 적어두다 구동사 pencil in을 활용하세요.`,targetEn:`Let's pencil in Friday at 11 AM.`,chunks:[`Let's`,`pencil in`,`Friday`,`at 11 AM.`],explanationKo:`확정 전 임시로 슬롯을 잡아둘 때 pencil in이 아주 유용합니다.`},{id:`d3-s10`,drillType:`konglish-fix`,promptKo:`"오후 3시가 제일 괜찮으세요(편하세요)?"`,promptEnHint:`시간 조율 동사 work의 쓰임을 확인하세요.`,targetEn:`Does 3 PM work best for you?`,wrongKonglishOption:`Does 3 PM okay best to you?`,explanationKo:`Does [시간] work (best) for you?가 정확한 문법과 어감입니다.`}],worksheetExam:[{id:`d3-ex01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`일정 표현 tight`,questionKo:`빈칸에 알맞은 형용사(1단어)를 넣어 "이번 주는 제 쪽 일정이 좀 빠듯하다(애매하다)"는 문장을 완성하세요.`,stimulusEn:`This week looks a bit __________ on my end.`,answer:`tight`,acceptableAlt:[`tricky`,`packed`],explanationKo:`일정 여유가 없어 조율이 애매할 때는 tight(또는 tricky/packed)를 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "제 쪽에서는(제 입장에서는)"을 뜻하는 전치사구(3단어)로 빈칸을 채우세요.`,stimulusEn:`Tomorrow morning looks pretty tight __________ __________ __________.`,answer:`on my end`,explanationKo:`on my end는 비즈니스 소통에서 책임을 명확히 하면서도 완곡함을 더합니다.`}},{id:`d3-ex02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`일정 연기 push back`,questionKo:`빈칸에 알맞은 구동사(2단어)를 넣어 "마감일을 금요일로 미룰 수 있을까요?"를 완성하세요.`,stimulusEn:`Could we __________ __________ the deadline to Friday?`,answer:`push back`,explanationKo:`일정이나 마감일을 뒤로 늦출 때는 push back을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 대명사 it을 포함하여 "그것을 목요일로 미루다"(3단어)로 빈칸을 채우세요.`,stimulusEn:`Could we __________ __________ __________ to Thursday?`,answer:`push it back`,explanationKo:`대명사 목적어 it은 반드시 구동사 사이(push it back)에 넣습니다.`}},{id:`d3-ex03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`만남 선약 have plans`,questionKo:`빈칸에 알맞은 명사(복수형 1단어)를 넣어 "이번 주말에 가족과 약속이 있다"는 문장을 완성하세요.`,stimulusEn:`I already have __________ with my family this weekend.`,answer:`plans`,explanationKo:`선약·약속이 있다는 표현은 관사 없이 복수형 have plans를 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 격식 있는 비즈니스 이메일에서 "선약"을 뜻하는 2단어(관사 제외)를 쓰세요.`,stimulusEn:`I apologize, as I have a __________ __________ that afternoon.`,answer:`prior commitment`,explanationKo:`a prior commitment가 공식 석상·이메일 표준 표현입니다.`}},{id:`d3-ex04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`관용구 rain check`,questionKo:`빈칸에 알맞은 명사구(2단어)를 넣어 "커피는 아쉽지만 다음을 기약해도 될까요?"를 완성하세요.`,stimulusEn:`I'm slammed right now—can I take a __________ __________ on coffee?`,answer:`rain check`,explanationKo:`take a rain check (on ~)는 초대를 정중히 다음 기회로 미루는 관용구입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "가일정으로 일단 적어두자"에 알맞은 구동사(2단어)를 넣으세요.`,stimulusEn:`Let's __________ __________ Wednesday at 10 AM for now.`,answer:`pencil in`,explanationKo:`임시 일정 등록은 pencil in입니다.`}},{id:`d3-ex05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`연속 회의 back-to-back`,questionKo:`빈칸에 하이픈(-)을 포함한 형용사(1단어)를 넣어 "연달아 이어지는 회의"를 완성하세요.`,stimulusEn:`I've been stuck in __________ calls since 9 AM.`,answer:`back-to-back`,explanationKo:`쉬는 시간 없이 이어지는 일정은 back-to-back calls / meetings라고 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "오후 3시 이후엔 일정이 텅 비어(활짝 열려) 있어요" 빈칸(2단어)을 채우세요.`,stimulusEn:`My calendar is __________ __________ after 3 PM.`,answer:`wide open`,explanationKo:`일정이 완전히 비어 있을 때 wide open을 씁니다.`}},{id:`d3-ex06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`ambiguous 콩글리시 함정`,questionKo:`동료가 내일 점심 미팅을 제안했을 때 "내일은 시간이 좀 애매하네요"를 가장 원어민답게 표현한 문장은?`,stimulusEn:`한국어 "애매하다"의 문맥상 의미를 생각해보세요.`,options:[`Tomorrow is very ambiguous for my lunch.`,`Tomorrow looks a bit tight on my end.`,`My schedule has vague meaning tomorrow.`,`Tomorrow time is obscure to me.`],answer:`Tomorrow looks a bit tight on my end.`,explanationKo:`ambiguous, vague, obscure는 모두 "글이나 말의 뜻이 모호하다"는 뜻이지 일정이 빠듯할 때 쓰지 않습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "대신 금요일 정오는 어떠세요?" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`Would Friday at noon __________ instead?`,answer:`work`,explanationKo:`Would [시간] work instead? 구문입니다.`}},{id:`d3-ex07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`move up vs push back 방향`,questionKo:`원래 **목요일**로 예정된 발표가 **화요일**로 변경되었을 때 알맞은 문장은?`,stimulusEn:`목요일(Thu) → 화요일(Tue)로 날짜가 바뀐 상황입니다.`,options:[`They pushed the presentation back to Tuesday.`,`They moved the presentation up to Tuesday.`,`They took a rain check on Tuesday.`,`They locked the presentation out of Tuesday.`],answer:`They moved the presentation up to Tuesday.`,explanationKo:`목요일에서 화요일로 시점이 더 빨라졌으므로(앞당겨졌으므로) moved ~ up to Tuesday가 정답입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 반대로 화요일 회의를 금요일로 늦췄다면? 빈칸(2단어, 과거형 포함)을 쓰세요.`,stimulusEn:`They __________ the meeting __________ to Friday. (공백으로 구분)`,answer:`pushed back`,explanationKo:`뒤로 늦추는 것은 pushed ~ back입니다.`}},{id:`d3-ex08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`참석 가능 여부 make it`,questionKo:`저녁 모임 초대에 "아쉽게도 오늘 저녁엔 참석하기 어려울 것 같아요"라고 정중히 답할 때 가장 자연스러운 표현은?`,stimulusEn:`빈칸에 들어갈 자연스러운 구문을 고르세요: "I’m afraid I won’t be able to __________ tonight."`,options:[`make it`,`do arrival`,`keep a promise`,`enter there`],answer:`make it`,explanationKo:`시간에 맞춰 도착하거나 모임에 참석하다는 뜻으로 make it이 일상과 비즈니스 모두에서 가장 널리 쓰입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "내일 제 생일 파티에 오실 수 있나요?" (Can you / make it / to my birthday party / tomorrow?)`,stimulusEn:`빈칸 2단어: Can you __________ __________ to my birthday party tomorrow?`,answer:`make it`,explanationKo:`Can you make it to [장소/행사]? 패턴입니다.`}},{id:`d3-ex09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`reschedule 전치사 호응`,questionKo:`다음 빈칸에 들어갈 전치사로 가장 알맞은 것은?`,stimulusEn:`Would it be possible to reschedule our check-in ______ next Wednesday?`,options:[`for`,`at`,`with`,`about`],answer:`for`,explanationKo:`reschedule A for [새로운 날짜/요일] 형태로 전치사 for(또는 to)를 사용하여 새 일정을 지정합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 회의를 "30분만큼" 뒤로 미룰 때 시간 차이 앞에 쓰는 전치사(1단어)는?`,stimulusEn:`Let’s push the call back __________ 30 minutes.`,answer:`by`,explanationKo:`차이·간격을 나타낼 때는 전치사 by(by 30 minutes, by two days)를 씁니다.`}},{id:`d3-ex10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`짬을 내다 구동사`,questionKo:`종일 바쁘지만 급한 안건을 위해 "오후 4시쯤 10분 정도 짧게 짬을 내어 일정을 끼워 넣을 수 있다"에 알맞은 표현은?`,stimulusEn:`I can __________ a quick 10-minute chat around 4 PM.`,options:[`squeeze in`,`drop off`,`head out`,`lose track of`],answer:`squeeze in`,explanationKo:`빡빡한 틈 사이에 쥐어짜듯 시간을 내어 끼워 넣는다는 뜻으로 squeeze in이 정확합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "최종 확정하다"를 뜻하는 구동사(2단어)를 넣어 문장을 완성하세요.`,stimulusEn:`Awesome, let's __________ __________ Friday at 2 PM!`,answer:`lock in`,explanationKo:`일정을 최종 확정할 때는 lock in을 씁니다.`}},{id:`d3-ex11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`완곡 거절 + 역제안 배열`,questionKo:`주어진 청크를 배열하여 세련된 일정 역제안 문장을 완성하세요.`,stimulusEn:`[ work / afternoon / instead? / Would / Thursday ]`,answer:`Would Thursday afternoon work instead?`,explanationKo:`Would + [대안 시간] + work + instead? 어순을 입에 완전히 익혀두세요.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "대신 다음 주 월요일 오전이 괜찮으실까요?" (Would / next Monday morning / work / instead?)`,stimulusEn:`영문 전체를 작성하세요 (물음표 포함).`,answer:`Would next Monday morning work instead?`,explanationKo:`시간 명사구만 갈아 끼우면 수백 가지 상황에 즉시 응용됩니다.`}},{id:`d3-ex12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`push back 요청문 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 정중한 일정 연기 요청문을 작성하세요.`,stimulusEn:`[ our sync / Could we / to 3 PM / push / back / instead? ]`,answer:`Could we push our sync back to 3 PM instead?`,acceptableAlt:[`Could we push back our sync to 3 PM instead?`],explanationKo:`push our sync back(또는 push back our sync) + to 3 PM + instead? 구조입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "점심 약속을 1시로 뒤로 미뤄도 될까요?" (Could we / push lunch back / to 1 PM?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Could we push lunch back to 1 PM?`,explanationKo:`push [일정] back to [새 시각] 패턴입니다.`}},{id:`d3-ex13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`How does ~ sound 제안문`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용하여 문장을 완성하세요.`,stimulusEn:`우리말: 목요일 오후 2시 반은 어떠세요? (How / does / Thursday at 2:30 PM / sound?)`,answer:`How does Thursday at 2:30 PM sound?`,explanationKo:`How does [제안 시간] sound?는 상대의 의향을 부드럽게 물어보는 핵심 구문입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "몇 시가 가장 편하신가요?" (What time / works best / for you?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`What time works best for you?`,explanationKo:`단수 의문사 주어 What time에 맞춰 동사 works에 -s를 붙입니다.`}},{id:`d3-ex14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장을 오늘 배운 표현(tight on my end, plans)을 사용하여 바르게 고쳐 쓰세요.`,stimulusEn:`오류 문장: Tonight is ambiguous on my end because I have a promise.`,answer:`Tonight looks tight on my end because I have plans.`,acceptableAlt:[`Tonight is tight on my end because I have plans.`,`Tonight is a bit tight on my end because I have plans.`],explanationKo:`ambiguous → tight, a promise → plans로 바꾸면 단번에 원어민 영어가 됩니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: Could we delay it? → push / it / back을 쓴 5단어 의문문으로 바꾸세요.`,stimulusEn:`힌트: Could we ~ ?`,answer:`Could we push it back?`,explanationKo:`대명사 it을 가운데 넣어 Could we push it back?으로 씁니다.`}},{id:`d3-ex15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`실전 통문장 영작`,questionKo:`다음 우리말을 영어로 자연스럽게 작성하세요.`,stimulusEn:`우리말: 일단 금요일 오전 10시로 가일정을 잡아두죠. (힌트: Let’s / pencil in / Friday at 10 AM.)`,answer:`Let's pencil in Friday at 10 AM.`,explanationKo:`Let's pencil in [요일 + 시각]으로 가볍게 캘린더 슬롯을 확보할 수 있습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "좋습니다, 목요일 오후 3시로 확정하죠." (Great, / let’s lock in / Thursday at 3 PM.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Great, let's lock in Thursday at 3 PM.`,explanationKo:`확정할 때는 lock in을 사용합니다.`}}],tutorScenario:{openingQuestionEn:`Hi! Could we hop on a 30-minute call tomorrow at 10 AM to go over the project timeline?`,openingQuestionKo:`안녕하세요! 프로젝트 일정을 점검하기 위해 내일 오전 10시에 30분 정도 통화 가능하실까요? (바쁘다고 가정하고 정중히 다른 시간을 역제안해보세요!)`,followUpQuestionEn:`Thursday afternoon works for me! Anytime after 2 PM is wide open—what exact time should we lock in?`,followUpQuestionKo:`목요일 오후 좋네요! 2시 이후론 다 비어 있는데 몇 시로 최종 확정할까요?`,recommendedChunks:[`looks a bit tight on my end`,`back-to-back meetings`,`push it back to ~`,`Would ~ work instead?`,`let's lock in ~`],modelAnswerEn:`Tomorrow morning looks a bit tight on my end since I'm in back-to-back meetings until noon. Would Thursday afternoon around 3 PM work instead?`}},i={dayNumber:4,weekNumber:1,cefrLevel:`a2`,dayBadge:`DAY 04 · 마감 기한 & 글로벌 협업 싱크`,categoryLabel:`실무 이메일 · 화상회의 필수 영어`,title:`금요일까지 마무리해서 공유드릴게요`,subtitle:`치명적인 마감 전치사 실수(by vs until)를 완벽히 잡고 신뢰감을 주는 업무 보고 문장 만들기`,heroImage:`assets/scene_video_call.jpg`,secondaryImage:`assets/office_sitcom_scene.jpg`,estimatedSprintMin:7,estimatedLectureMin:42,keyExpression:`wrap ~ up by Friday and keep you in the loop`,keySentenceByTier:{a1:`I will finish the work by Friday and send it to you.`,a2:`I will finish the draft by Friday and share it with you.`,b1:`I'll wrap up the first draft by Friday afternoon and keep you in the loop.`,b2:`We're right on track to wrap up the final deliverables by EOD Friday, and I'll be sure to keep everyone in the loop.`,c1:`All workstreams are tracking smoothly toward our EOD Friday milestone, and I will circulate a concise progress summary as soon as we finalize QA.`,c2:`We remain squarely on track to sign off on the final deliverables by EOD Friday; rest assured I’ll keep all stakeholders closely apprised of any developments.`},youtubeVideo:e[4],readingPassage:{titleEn:`Why "By Friday" and "Until Friday" Change Everything at Work`,titleKo:`직장에서 "by Friday"와 "until Friday"가 완전히 다른 이유`,genreBadge:`글로벌 오피스 실무 노트 · Lv.2`,estimatedMin:6,paragraphsEn:[`In Korean, a single word "까지" covers both deadlines and continuous states. In English, however, mixing up "by" and "until" can cause instant confusion on a global project.`,`Use "by" whenever a task finishes at or before a deadline: "I will submit the report by 5 PM." Use "until" only when an activity continues steadily up to that point: "I will be in Seoul until Friday."`,`Pairing the right preposition with clear status phrases like "on track", "wrap it up", and "keep you in the loop" helps remote teams trust your timeline without sending constant follow-up messages.`],paragraphsSlash:[`In Korean, / a single word "까지" covers both deadlines / and continuous states. / In English, however, / mixing up "by" and "until" / can cause instant confusion on a global project.`,`Use "by" / whenever a task finishes at or before a deadline: / "I will submit the report by 5 PM." / Use "until" only when an activity continues steadily / up to that point: / "I will be in Seoul until Friday."`,`Pairing the right preposition / with clear status phrases like "on track", "wrap it up", and "keep you in the loop" / helps remote teams trust your timeline / without sending constant follow-up messages.`],paragraphsKo:[`한국어에서는 “까지”라는 한 단어가 마감 기한과 상태의 지속을 모두 나타냅니다. 하지만 영어에서 by와 until을 혼동하면 글로벌 프로젝트에서 즉각 오해가 생깁니다.`,`업무가 특정 기한 전에 완료되어야 할 때는 반드시 by를 씁니다: “오후 5시까지 보고서를 제출하겠습니다.” 반대로 상태나 행동이 그 시점까지 쭉 이어질 때만 until을 씁니다: “금요일까지 서울에 머물 예정입니다.”`,`정확한 전치사에 on track(순조롭게 진행 중), wrap it up(마무리하다), keep you in the loop(계속 공유하다) 같은 명확한 표현을 결합하면, 원격 팀원들이 재촉 메시지를 보내지 않아도 당신의 일정을 신뢰하게 됩니다.`],keyExpressions:[`by vs until`,`wrap it up`,`on track`,`keep you in the loop`,`EOD Friday`],comprehensionQuiz:[{id:`d4-rq01`,questionKo:`보고서 제출처럼 특정 기한 전에 끝나는 “마감”에 써야 하는 전치사는?`,options:[`by`,`until`,`during`],answer:`by`,explanationKo:`둘째 문단 "Use by whenever a task finishes at or before a deadline"이 정답 근거입니다.`},{id:`d4-rq02`,questionKo:`다음 중 전치사 until이 가장 자연스럽게 쓰인 문장은?`,options:[`I will submit the report until 5 PM.`,`I will stay in Seoul until Friday.`,`Please reply until tomorrow morning.`],answer:`I will stay in Seoul until Friday.`,explanationKo:`머무르는 상태가 금요일까지 계속 이어지므로 stay ~ until Friday가 정확합니다.`},{id:`d4-rq03`,questionKo:`원격 팀원들이 불필요한 재촉 메시지를 줄이고 일정을 신뢰하게 만드는 핵심 습관은?`,options:[`답장을 최대한 늦게 보내기`,`정확한 전치사와 명확한 진행 상태 표현(on track, keep in the loop)을 함께 사용하기`,`마감일을 일부러 말하지 않기`],answer:`정확한 전치사와 명확한 진행 상태 표현(on track, keep in the loop)을 함께 사용하기`,explanationKo:`셋째 문단 내용을 확인하세요.`}]},vocabList:[{id:`d4-v01`,word:`by Friday`,phonetic:`/baɪ ˈfraɪdeɪ/`,pos:`전치사구`,meaningKo:`금요일까지 (늦어도 금요일 안으로 완료)`,meaningEn:`no later than Friday (deadline)`,nuanceTipKo:`제출·마감·완료 시점에는 무조건 by입니다! until Friday라고 쓰면 "금요일까지 계속 붙잡고만 있겠다"는 엉뚱한 뜻이 됩니다.`,exampleEn:`Please submit your expense report by Friday.`,exampleKo:`금요일까지 경비 정산서를 제출해 주세요.`},{id:`d4-v02`,word:`until Friday`,phonetic:`/ənˈtɪl ˈfraɪdeɪ/`,pos:`전치사구`,meaningKo:`금요일까지 쭉 (동작·상태의 지속)`,meaningEn:`continuing continuously up to Friday`,nuanceTipKo:`휴가 중이다(on vacation), 기다리다(wait), 머무르다(stay)처럼 쭉 이어지는 상태와 결합합니다.`,exampleEn:`Sarah will be out of the office until Friday.`,exampleKo:`사라는 금요일까지 쭉 부재중(휴가)일 예정입니다.`},{id:`d4-v03`,word:`wrap up`,phonetic:`/ræp ʌp/`,pos:`구동사`,meaningKo:`(업무·회의·프로젝트를) 잘 마무리하다`,meaningEn:`bring a task or meeting to a successful conclusion`,nuanceTipKo:`선물을 포장지(wrap)로 깔끔히 감싸듯, 진행하던 일을 매듭지을 때 finish보다 훨씬 세련된 실무 표현입니다.`,exampleEn:`Let's wrap up this section and move to Q&A.`,exampleKo:`이 파트는 이만 마무리하고 질의응답으로 넘어가죠.`},{id:`d4-v04`,word:`keep ~ in the loop`,phonetic:`/kiːp ɪn ðə luːp/`,pos:`관용구`,meaningKo:`~에게 진행 상황을 계속 공유하다(소외되지 않게 알리다)`,meaningEn:`keep someone informed with updates inside the communication circle`,nuanceTipKo:`이메일 참조(CC)에 넣거나 슬랙으로 중간 경과를 공유하겠다고 약속할 때 최고의 표현입니다.`,exampleEn:`I'll keep you in the loop as soon as I hear back.`,exampleKo:`답변 받는 대로 진행 상황 바로 공유드릴게요.`},{id:`d4-v05`,word:`on the same page`,phonetic:`/ɑːn ðə seɪm peɪdʒ/`,pos:`관용구`,meaningKo:`서로 이해·생각이 일치하는 (싱크가 맞은 상태)`,meaningEn:`in agreement and sharing the same understanding`,nuanceTipKo:`회의 시작이나 끝에 오해가 없는지 점검할 때 "Just to make sure we're on the same page"라고 자주 씁니다.`,exampleEn:`Quick sync to make sure everyone is on the same page.`,exampleKo:`모두 같은 내용을 공유하고 있는지 맞추기 위한 짧은 싱크 미팅입니다.`},{id:`d4-v06`,word:`on track`,phonetic:`/ɑːn træk/`,pos:`전치사구`,meaningKo:`계획·목표대로 순조롭게 진행 중인`,meaningEn:`progressing as planned toward a goal or deadline`,nuanceTipKo:`기차가 선로(track) 위를 벗어나지 않고 잘 달리는 모습! 반대로 일정이 밀리면 off track을 씁니다.`,exampleEn:`Are we still on track for the May 15 release?`,exampleKo:`5월 15일 출시 일정대로 순조롭게 진행 중인가요?`},{id:`d4-v07`,word:`give ~ a heads-up`,phonetic:`/ɡɪv ə ˈhedz ʌp/`,pos:`관용구`,meaningKo:`~에게 미리 귀띔해주다 (사전 공지하다)`,meaningEn:`warn or inform someone in advance so they are prepared`,nuanceTipKo:`갑작스러운 변경이나 일정을 미리 살짝 알려줄 때 "Just wanted to give you a quick heads-up!"이라고 시작해보세요.`,exampleEn:`Thanks for giving us a heads-up about the server maintenance.`,exampleKo:`서버 점검 일정을 미리 귀띔해 주셔서 감사합니다.`},{id:`d4-v08`,word:`circle back`,phonetic:`/ˈsɜːrkl bæk/`,pos:`구동사`,meaningKo:`(확인 후 나중에) 다시 논의하다, 회신하다`,meaningEn:`return to discuss a topic again later after gathering info`,nuanceTipKo:`회의 중 당장 답하기 어려운 질문이 나왔을 때 "Let me check the numbers and circle back to you"라고 넘기면 완벽합니다.`,exampleEn:`Let's circle back to the budget issue next week.`,exampleKo:`예산 이슈는 다음 주에 다시 돌아와 논의하죠.`},{id:`d4-v09`,word:`by EOD (end of day)`,phonetic:`/baɪ ˈiː oʊ ˈdiː/`,pos:`실무 약어구`,meaningKo:`오늘 업무 종료 전까지 (금일 마감 전까지)`,meaningEn:`by the end of the business day`,nuanceTipKo:`글로벌 슬랙·이메일 1순위 약어! 주간 마감은 by EOW(end of week)로 씁니다.`,exampleEn:`I can send over the revised slides by EOD today.`,exampleKo:`오늘 퇴근 전까지 수정된 슬라이드를 보내드릴 수 있습니다.`},{id:`d4-v10`,word:`touch base`,phonetic:`/tʌtʃ beɪs/`,pos:`관용구`,meaningKo:`짧게 연락해 진행 상황을 확인하다`,meaningEn:`briefly make contact or check in with someone`,nuanceTipKo:`야구 주자가 베이스를 찍듯 무겁지 않게 안부 겸 현황을 체크할 때 씁니다.`,exampleEn:`Just wanted to touch base on the partnership proposal.`,exampleKo:`파트너십 제안 건이 어떻게 되어가는지 짧게 확인차 연락드렸어요.`},{id:`d4-v11`,word:`flesh out`,phonetic:`/fleʃ aʊt/`,pos:`구동사`,meaningKo:`(초안·아이디어 뼈대에) 구체적인 살을 붙이다`,meaningEn:`add more details to a rough plan or outline`,nuanceTipKo:`러프한 기획안을 구체화할 때 add details보다 훨씬 생동감 넘치는 고급 구동사입니다.`,exampleEn:`We need to flesh out the marketing strategy before Friday.`,exampleKo:`금요일 전까지 마케팅 전략에 구체적인 살을 붙여야 합니다.`},{id:`d4-v12`,word:`sign off on`,phonetic:`/saɪn ɔːf ɑːn/`,pos:`구동사`,meaningKo:`(안건·예산·디자인을) 최종 승인하다(컨펌하다)`,meaningEn:`give official approval for something`,nuanceTipKo:`한국 오피스의 "컨펌받다"는 영어에서 confirm보다 get approval이나 sign off on을 씁니다!`,exampleEn:`Did the VP sign off on the final budget yet?`,exampleKo:`부사장님이 최종 예산안을 승인하셨나요?`},{id:`d4-v13`,word:`loop ~ in`,phonetic:`/luːp ɪn/`,pos:`구동사`,meaningKo:`(이메일·대화 스레드에 담당자를) 초대해 합류시키다`,meaningEn:`include someone in an email thread or discussion`,nuanceTipKo:`이메일 CC에 누구를 추가하면서 "I'm looping in Alex from Legal"이라고 쓰면 현업 원어민 100% 표현입니다.`,exampleEn:`Let me loop in our lead engineer so he can weigh in.`,exampleKo:`수석 엔지니어 의견도 들을 수 있게 대화에 초대할게요.`},{id:`d4-v14`,word:`bottleneck`,phonetic:`/ˈbɑːtlnek/`,pos:`명사`,meaningKo:`병목 구간 (전체 일정을 지연시키는 막힌 지점)`,meaningEn:`a point of congestion slowing down the whole process`,nuanceTipKo:`프로젝트 지연 원인을 분석할 때 problem 대신 bottleneck을 쓰면 문제 해결 중심의 전문적인 인상을 줍니다.`,exampleEn:`Legal review is the main bottleneck right now.`,exampleKo:`현재 법무 검토 단계가 가장 큰 병목 구간입니다.`},{id:`d4-v15`,word:`hand off`,phonetic:`/hænd ɔːf/`,pos:`구동사`,meaningKo:`(다음 담당자·팀에게 업무를) 인계하다, 넘기다`,meaningEn:`pass responsibility or deliverables to the next person/team`,nuanceTipKo:`디자인이 끝나 개발팀으로 넘길 때(design handoff)처럼 부서 간 바통 터치에 쓰는 핵심 표현입니다.`,exampleEn:`We'll hand off the final specs to engineering by Thursday.`,exampleKo:`목요일까지 개발팀에 최종 기획 사양서를 인계할 예정입니다.`}],dialogue:[{id:`d4-t1`,speaker:`Marcus`,roleLabel:`뉴욕 오피스 디자인 리드`,voicePitch:.92,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Hi Chloe! Thanks for hopping on Zoom. Just wanted to touch base on the onboarding redesign.`,slashBroken:`Hi Chloe! / Thanks for hopping on Zoom. / Just wanted to touch base / on the onboarding redesign.`,korean:`안녕 클로이! 줌 미팅 들어와 줘서 고마워. 온보딩 개편 건 진행 상황 짧게 체크하려고 불렀어.`,keyHighlight:`touch base on ~`,noteKo:`화상회의에 접속하다는 hop on Zoom / hop on a call로 가볍게 표현합니다.`},{id:`d4-t2`,speaker:`Chloe`,roleLabel:`서울 프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`pan-right`,english:`Happy to! Good news—we're right on track. My team fleshed out the user flow yesterday.`,slashBroken:`Happy to! / Good news—we're right on track. / My team fleshed out the user flow / yesterday.`,korean:`반가워! 좋은 소식이야, 일정대로 순조롭게 진행 중이야. 어제 우리 팀이 유저 플로우를 구체화했거든.`,keyHighlight:`right on track / fleshed out`,noteKo:`상대방이 고마움을 표할 때 "Happy to!(기꺼이요!)"로 화답하면 분위기가 밝아집니다.`},{id:`d4-t3`,speaker:`Marcus`,roleLabel:`뉴욕 오피스 디자인 리드`,voicePitch:.92,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`pan-left`,english:`Awesome! When do you think you'll be able to wrap up the final copy so we can plug it in?`,slashBroken:`Awesome! / When do you think / you'll be able to wrap up the final copy / so we can plug it in?`,korean:`멋진데! 디자인에 바로 얹을 수 있게 최종 문구 작업은 언제쯤 마무리할 수 있을 것 같아?`,keyHighlight:`wrap up the final copy`,noteKo:`문구나 데이터를 템플릿에 끼워 넣는다는 뜻으로 plug it in을 유용하게 씁니다.`},{id:`d4-t4`,speaker:`Chloe`,roleLabel:`서울 프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`I'll wrap it up by Friday afternoon, though our legal lead is out of office until Thursday.`,slashBroken:`I'll wrap it up by Friday afternoon, / though our legal lead is out of office / until Thursday.`,korean:`금요일 오후까지는 마무리할게. 다만 법무팀 리드 분이 목요일까지 쭉 휴가 중이긴 해.`,keyHighlight:`by Friday ~ until Thursday`,noteKo:`한 문장 안에서 완료 마감(by Friday)과 부재 지속(until Thursday)의 대조를 완벽히 느껴보세요!`},{id:`d4-t5`,speaker:`Marcus`,roleLabel:`뉴욕 오피스 디자인 리드`,voicePitch:.92,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`Got it—thanks for the heads-up! Once Legal signs off on it, please loop in our frontend engineer.`,slashBroken:`Got it—thanks for the heads-up! / Once Legal signs off on it, / please loop in our frontend engineer.`,korean:`알겠어, 미리 귀띔해 줘서 고마워! 법무팀 최종 승인이 나면 우리 프론트엔드 엔지니어도 스레드에 초대해 줘.`,keyHighlight:`signs off on it / loop in`,noteKo:`최종 컨펌(sign off on)과 담당자 참조 초대(loop in)가 자연스럽게 연결됩니다.`},{id:`d4-t6`,speaker:`Chloe`,roleLabel:`서울 프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Will do! Glad we're on the same page. I'll keep you in the loop via Slack by EOD Thursday.`,slashBroken:`Will do! / Glad we're on the same page. / I'll keep you in the loop via Slack / by EOD Thursday.`,korean:`그렇게 할게! 서로 싱크가 딱 맞아서 다행이다. 목요일 퇴근 전까지 슬랙으로 중간 경과 공유할게.`,keyHighlight:`keep you in the loop ~ by EOD`,noteKo:`"Will do!"는 "I will do that"을 경쾌하고 프로답게 줄인 실무 1순위 대답입니다.`}],grammarSections:[{title:`원리 01 · 한국인 실무 영어 오해 1위: 완료 시점 [by] vs. 지속 기간 [until]`,coreFormula:`by + 시점 (그전까지 1회 완료·제출) ↔ until + 시점 (그때까지 쭉 상태 지속)`,wrongKonglish:`Please send me the revised file until Friday.`,rightNative:`Please send me the revised file by Friday.`,explanationKo:`한국어 조사 "~까지" 하나에 영어 전치사 두 개(by, until)가 겹쳐 있어 한국 직장인의 90%가 실수합니다. 파일을 보내거나(send), 작업을 끝내거나(wrap up), 회신하는(reply) 것처럼 "특정 데드라인 이전에 딱 완료되는 행동"은 무조건 by를 씁니다. 반면 사무실에 남아 있거나(stay), 휴가 중이거나(be away), 기다리는(wait) "연속 상태"만 until을 씁니다.`,registerSpectrum:{casual:`Can you get back to me by tonight?`,standard:`I'll wrap up the report by Friday afternoon.`,formal:`Kindly submit all required documentation by EOD May 30.`}},{title:`원리 02 · 콩글리시 "메일 체크 & 컨펌 부탁드려요" 완벽 교정`,coreFormula:`check my email / review the draft / sign off on the plan`,wrongKonglish:`Please check my mail and confirm the budget.`,rightNative:`Could you take a look at my email and sign off on the budget?`,explanationKo:`① 단독 명사 mail은 우체부가 배달하는 종이 우편물이므로 전자우편은 반드시 email이라고 써야 합니다. ② 영어 동사 confirm은 "사실 여부나 예약을 재확인하다"라는 뜻이지 상사가 결재·승인하다는 뜻이 아닙니다! 검토 요청은 review / take a look at, 최종 승인은 approve 또는 sign off on을 사용하세요.`,registerSpectrum:{casual:`Did you get a chance to look over my email?`,standard:`Could you review the draft and let me know your thoughts?`,formal:`We are awaiting executive sign-off on the Q4 budget proposal.`}},{title:`원리 03 · 글로벌 원격 협업 신뢰도를 높이는 "선제 공유" 3대 구문`,coreFormula:`give you a heads-up (사전 귀띔) → keep you in the loop (중간 공유) → circle back (확인 후 회신)`,wrongKonglish:`I will notice you beforehand and share continuously.`,rightNative:`Just wanted to give you a heads-up, and I'll keep you in the loop.`,explanationKo:`글로벌 팀에서 가장 일 잘한다는 평가를 받는 비결은 투명한 진행 공유입니다. 이슈가 예상될 때 미리 알리는 give a heads-up, 진행 과정에서 소외되지 않게 챙기는 keep ~ in the loop, 모르는 걸 즉답하지 않고 확인 후 돌아오는 circle back — 이 세 가지만 구사해도 커뮤니케이션 품격이 달라집니다.`,registerSpectrum:{casual:`Just a quick heads-up—the build might take 10 extra minutes.`,standard:`I'll keep you in the loop as soon as we hear from the client.`,formal:`Allow me to verify the figures and circle back to you by tomorrow morning.`}}],sprintDrills:[{id:`d4-s01`,drillType:`konglish-fix`,promptKo:`"금요일까지 수정된 보고서를 보내주세요." — 바른 전치사는?`,promptEnHint:`제출·전송은 마감 데드라인(완료) 동작입니다!`,targetEn:`Please send me the revised report by Friday.`,wrongKonglishOption:`Please send me the revised report until Friday.`,explanationKo:`특정 기한 안에 완료해야 하는 제출·발송에는 반드시 전치사 by를 씁니다.`},{id:`d4-s02`,drillType:`chunk-build`,promptKo:`금요일 오후까지 초안을 마무리할게요.`,promptEnHint:`마무리하다 wrap up + 마감 by Friday afternoon`,targetEn:`I'll wrap up the first draft by Friday afternoon.`,chunks:[`I'll wrap up`,`the first draft`,`by Friday`,`afternoon.`],explanationKo:`wrap up + 목적어 + by [마감 시점]은 실무 일정 약속의 정석입니다.`},{id:`d4-s03`,drillType:`active-blank`,promptKo:`사라는 목요일까지 쭉 휴가(부재중)일 예정입니다.`,promptEnHint:`부재 상태가 목요일까지 계속 이어지므로 알맞은 전치사를 쓰세요.`,targetEn:`Sarah will be out of the office until Thursday.`,blankData:{before:`Sarah will be out of the office`,answer:`until`,after:`Thursday.`,firstLetterHint:`u____ (5글자)`},explanationKo:`계속 이어지는 상태(out of the office)에는 지속 전치사 until을 씁니다.`},{id:`d4-s04`,drillType:`chunk-build`,promptKo:`답변 받는 대로 진행 상황을 계속 공유드릴게요.`,promptEnHint:`소통 고리 안에 두다 keep you in the loop를 조립하세요.`,targetEn:`I'll keep you in the loop once I hear back.`,chunks:[`I'll keep you`,`in the loop`,`once I`,`hear back.`],explanationKo:`hear back(답신을 받다)과 keep you in the loop는 환상의 비즈니스 짝꿍입니다.`},{id:`d4-s05`,drillType:`konglish-fix`,promptKo:`"제 이메일 확인해 보시고 예산안 최종 승인(컨펌) 부탁드립니다."`,promptEnHint:`mail vs email, confirm vs sign off on 차이를 확인하세요.`,targetEn:`Could you check my email and sign off on the budget?`,wrongKonglishOption:`Could you check my mail and confirm about the budget?`,explanationKo:`전자우편은 email, 예산·기획 최종 승인은 sign off on을 씁니다.`},{id:`d4-s06`,drillType:`active-blank`,promptKo:`5월 출시 목표대로 순조롭게 진행 중입니다.`,promptEnHint:`기차 선로 위에 잘 올라와 있다는 명사(1단어)를 넣으세요.`,targetEn:`We are right on track for the May launch.`,blankData:{before:`We are right on`,answer:`track`,after:`for the May launch.`,firstLetterHint:`t____ (5글자)`},explanationKo:`be on track for ~ 는 일정·목표대로 차질 없이 가고 있다는 핵심 표현입니다.`},{id:`d4-s07`,drillType:`chunk-build`,promptKo:`모두 같은 생각(이해)을 공유하고 있는지 확인하고 싶습니다.`,promptEnHint:`같은 페이지를 보고 있다 on the same page를 활용하세요.`,targetEn:`I want to make sure we are on the same page.`,chunks:[`I want to`,`make sure`,`we are`,`on the same page.`],explanationKo:`오해 없이 싱크를 맞출 때 쓰는 글로벌 미팅 필수 문장입니다.`},{id:`d4-s08`,drillType:`active-blank`,promptKo:`일정 변경에 대해 미리 귀띔해 주셔서 감사합니다.`,promptEnHint:`사전 공지/귀띔을 뜻하는 하이픈 명사(heads-up)에서 빈칸을 채우세요.`,targetEn:`Thanks for giving me a heads-up about the schedule change.`,blankData:{before:`Thanks for giving me a`,answer:`heads-up`,after:`about the schedule change.`,firstLetterHint:`h____-u_`},explanationKo:`give someone a heads-up은 미리 언질을 주어 대비하게 해준다는 뜻입니다.`},{id:`d4-s09`,drillType:`chunk-build`,promptKo:`수치를 확인해 본 뒤에 내일 다시 회신드릴게요.`,promptEnHint:`다시 돌아와 논의하다 circle back to you를 배열하세요.`,targetEn:`Let me check the numbers and circle back to you tomorrow.`,chunks:[`Let me check`,`the numbers`,`and circle back`,`to you tomorrow.`],explanationKo:`모르는 질문에 당황하지 않고 프로답게 확인 후 답변하겠다고 말할 때 씁니다.`},{id:`d4-s10`,drillType:`active-blank`,promptKo:`수석 엔지니어도 이 대화 스레드에 초대할게요.`,promptEnHint:`고리 안으로 불러들이다 ____ in (동사 1단어)`,targetEn:`Let me loop in our lead engineer on this thread.`,blankData:{before:`Let me`,answer:`loop`,after:`in our lead engineer on this thread.`,firstLetterHint:`l___ (4글자)`},explanationKo:`이메일 참조(CC)나 슬랙 채널에 담당자를 추가할 때 loop in을 씁니다.`}],worksheetExam:[{id:`d4-ex01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`마감 전치사 by`,questionKo:`빈칸에 알맞은 전치사(1단어)를 넣어 "수요일 정오까지 계약서에 서명해 주세요"를 완성하세요.`,stimulusEn:`Please sign and return the contract __________ Wednesday at noon.`,answer:`by`,explanationKo:`서명 후 반송하는 것은 마감 기한 내 완료 동작이므로 전치사 by가 정답입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "금일 오후 6시까지 사무실에 계속 남아 있을 예정이다" 빈칸 전치사(1단어)는?`,stimulusEn:`I will stay at the office __________ 6 PM today.`,answer:`until`,explanationKo:`머무르는 상태의 지속이므로 until을 씁니다.`}},{id:`d4-ex02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`마무리 구동사 wrap up`,questionKo:`빈칸에 알맞은 구동사(2단어)를 넣어 "오늘 퇴근 전까지 슬라이드 작업을 마무리하겠다"를 완성하세요.`,stimulusEn:`I'll __________ __________ the presentation deck by EOD today.`,answer:`wrap up`,explanationKo:`진행 중인 업무나 회의를 깔끔히 매듭지을 때 wrap up을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 대명사 it을 가운데 넣어 "그것을 내일까지 마무리하다"(3단어)를 쓰세요.`,stimulusEn:`We can __________ __________ __________ by tomorrow.`,answer:`wrap it up`,explanationKo:`타동사+부사 구동사이므로 대명사 it은 wrap it up 어순으로 들어갑니다.`}},{id:`d4-ex03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`진행 공유 in the loop`,questionKo:`빈칸에 알맞은 명사(1단어)를 넣어 "진행 상황을 계속 공유드리겠습니다"를 완성하세요.`,stimulusEn:`We will keep you in the __________ throughout the testing phase.`,answer:`loop`,explanationKo:`keep someone in the loop는 소통 고리 안에서 업데이트를 지속 공유한다는 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "서로 이해/싱크가 일치하는지 확인하다" 빈칸 명사(1단어)를 채우세요.`,stimulusEn:`Let's make sure both teams are on the same __________.`,answer:`page`,explanationKo:`on the same page 숙어입니다.`}},{id:`d4-ex04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`확인 후 재논의 circle back`,questionKo:`빈칸에 알맞은 구동사(2단어)를 넣어 "법무팀에 확인한 뒤 다시 회신드리겠습니다"를 완성하세요.`,stimulusEn:`Let me check with Legal and __________ __________ to you.`,answer:`circle back`,explanationKo:`정보를 확인한 뒤 해당 안건/상대에게 다시 돌아와 이야기할 때 circle back (to ~)을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "진행 현황을 짧게 체크하다"를 뜻하는 2단어 표현을 쓰세요.`,stimulusEn:`I just wanted to __________ __________ on the design timeline.`,answer:`touch base`,explanationKo:`touch base on ~ 은 가볍게 진행 상황을 점검할 때 씁니다.`}},{id:`d4-ex05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`최종 승인 sign off on`,questionKo:`빈칸에 알맞은 구동사(3단어, 현재원형)를 넣어 "디렉터가 신규 로고를 최종 승인해야 한다"를 완성하세요.`,stimulusEn:`Our creative director needs to __________ __________ __________ the new logo first.`,answer:`sign off on`,explanationKo:`공식 승인(컨펌)을 내리다는 sign off on + 목적어로 표현합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "기획안 뼈대에 구체적인 살을 붙이다" 구동사(2단어)를 넣으세요.`,stimulusEn:`Can you __________ __________ Section 2 with concrete examples?`,answer:`flesh out`,explanationKo:`아이디어에 세부 내용을 보강할 때는 flesh out을 씁니다.`}},{id:`d4-ex06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`by vs until 실전 구별`,questionKo:`다음 중 전치사 **by**와 **until**이 모두 어법상 올바르게 쓰인 문장은?`,stimulusEn:`완료 동작인지 지속 상태인지 동사의 성격을 먼저 파악하세요.`,options:[`Please finish the code until 5 PM, and wait here by 6 PM.`,`Please finish the code by 5 PM, and wait here until 6 PM.`,`I will return the book until Monday.`,`The store is open by 10 PM every night.`],answer:`Please finish the code by 5 PM, and wait here until 6 PM.`,explanationKo:`코드를 끝내는 것(finish)은 완료이므로 by 5 PM, 기다리는 것(wait)은 지속이므로 until 6 PM이 정확합니다. (가게 영업 지속도 open until 10 PM이어야 맞습니다.)`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이 쿠폰은 12월 31일까지 쭉 유효합니다"에 알맞은 전치사(1단어)는?`,stimulusEn:`This voucher is valid __________ December 31.`,answer:`until`,explanationKo:`유효한 상태(valid)가 그날까지 쭉 지속되므로 until(또는 through)을 씁니다.`}},{id:`d4-ex07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`실무 약어 EOD 의미`,questionKo:'해외 동료가 슬랙에 `"Could you share the link by EOD?"`라고 보냈을 때 정확한 의미는?',stimulusEn:`글로벌 오피스 표준 약어 EOD의 뜻을 고르세요.`,options:[`오늘 업무 종료(퇴근) 전까지 링크를 공유해 주세요.`,`비상 상황 발생 시에만 링크를 열어보세요.`,`부서장 결재 서류와 함께 우편으로 보내주세요.`,`다음 달 말일까지 링크를 유지해 주세요.`],answer:`오늘 업무 종료(퇴근) 전까지 링크를 공유해 주세요.`,explanationKo:`EOD는 End of Day(금일 일과 종료 시점)의 약자입니다. 참고로 EOW는 End of Week(이번 주 금요일 마감)입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "오늘 퇴근 전까지"를 뜻하는 2단어 구문(전치사 + 약어 대문자)을 쓰세요.`,stimulusEn:`I'll get this done __________ __________.`,answer:`by EOD`,explanationKo:`by EOD로 간결하게 데드라인을 표기합니다.`}},{id:`d4-ex08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`사전 귀띔 heads-up`,questionKo:`회의 시작 10분 전, 발표 자료 용량이 커서 로딩이 걸릴 수 있다고 동료에게 "미리 살짝 귀띔해주다"에 알맞은 표현은?`,stimulusEn:`Just wanted to ____________________ that the video file is quite heavy.`,options:[`give you a heads-up`,`make up for you`,`call it a day`,`take a rain check`],answer:`give you a heads-up`,explanationKo:`상대가 당황하지 않게 사전에 언질을 주는 것은 give someone a heads-up입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 상대방이 미리 알려줬을 때 "미리 귀띔해 줘서 고마워요!" (Thanks for / the heads-up!)`,stimulusEn:`빈칸 2단어: Thanks for __________ __________!`,answer:`the heads-up`,explanationKo:`실무 슬랙에서 매일 쓰이는 감사 인사입니다.`}},{id:`d4-ex09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`콩글리시 discuss about 교정`,questionKo:`다음 중 비즈니스 이메일 문장으로 어법상 **결함이 없는** 문장은?`,stimulusEn:`타동사와 전치사 중복 함정(discuss about, check mail)을 주의하세요.`,options:[`Let us discuss about the bottleneck tomorrow.`,`Did you check my mail regarding the schedule?`,`We handed off the final designs to the dev team yesterday.`,`Please confirm about my vacation until noon.`],answer:`We handed off the final designs to the dev team yesterday.`,explanationKo:`discuss는 타동사라 about을 쓰면 틀리고, 전자우편은 email, 휴가 승인은 approve by noon이어야 합니다. hand off A to B(A를 B에게 인계하다) 문장만 완벽합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "내일 그 병목 구간에 대해 논의하죠"에서 discuss 뒤 전치사 없이 3단어를 쓰세요.`,stimulusEn:`Let's __________ __________ __________ tomorrow. (discuss / the / bottleneck)`,answer:`discuss the bottleneck`,explanationKo:`discuss 뒤에 바로 목적어 the bottleneck을 씁니다.`}},{id:`d4-ex10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`일정 순항 on track`,questionKo:`팀장이 프로젝트가 지연 없이 예정대로 잘 가고 있는지 물었을 때 "네, 계획대로 순조롭게 진행 중입니다"에 해당하는 대답은?`,stimulusEn:`Manager: "How is the migration going?" → You: "____________________"`,options:[`Everything is right on track.`,`Everything is in my way.`,`We lost track of time.`,`It looks tight on my end.`],answer:`Everything is right on track.`,explanationKo:`right on track은 일정과 목표에서 벗어나지 않고 순항 중이라는 뜻입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 상대의 요청에 "네, 그렇게 하겠습니다!"라고 경쾌하고 프로답게 2단어로 답할 때는?`,stimulusEn:`A: "Please loop in Sarah on the email." → B: "__________ __________!"`,answer:`Will do`,explanationKo:`"Will do!"는 I will do it의 자연스러운 실무 축약 응답입니다.`}},{id:`d4-ex11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`마감 약속 + 공유 통문장 배열`,questionKo:`주어진 청크를 배열하여 신뢰감을 주는 업무 보고 문장을 완성하세요.`,stimulusEn:`[ in the loop. / by Friday / I will wrap up / and keep you / the draft ]`,answer:`I will wrap up the draft by Friday and keep you in the loop.`,explanationKo:`[마무리 약속] I will wrap up the draft by Friday + [지속 공유] and keep you in the loop.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "오늘 퇴근 전까지 수치를 확인해서 회신드릴게요." (I will check the numbers / and circle back to you / by EOD.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I will check the numbers and circle back to you by EOD.`,explanationKo:`circle back to you + by EOD 결합 문장입니다.`}},{id:`d4-ex12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`on the same page 구문 배열`,questionKo:`주어진 표현을 올바른 순서로 배열하여 문장을 완성하세요.`,stimulusEn:`[ on the same page / Let’s hop on / to make sure / a quick call / we are ]`,answer:`Let's hop on a quick call to make sure we are on the same page.`,explanationKo:`슬랙 텍스트로 오해가 생길 것 같을 때 바로 제안하기 좋은 실무 대표 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "파트너십 건 진행 상황을 짧게 확인차 연락드렸어요." (Just wanted to / touch base on / the partnership.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Just wanted to touch base on the partnership.`,explanationKo:`이메일 첫 줄 오프닝으로 매우 유용합니다.`}},{id:`d4-ex13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`loop in 실무 문장 작성`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용하여 문장을 완성하세요.`,stimulusEn:`우리말: 법무팀에서 최종 승인하면 개발 리드를 대화에 초대할게요.
(힌트: Once Legal signs off on it, / I will loop in / our tech lead.)`,answer:`Once Legal signs off on it, I will loop in our tech lead.`,explanationKo:`시간·조건 부사절(Once + 현재시제 signs off on it)과 주절(I will loop in ~)의 시제 일치에 유의하세요.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "목요일까지 최종 기획안을 개발팀에 인계하겠습니다." (We will hand off / the final specs / to the dev team / by Thursday.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`We will hand off the final specs to the dev team by Thursday.`,explanationKo:`hand off A to B + by [마감일] 구조입니다.`}},{id:`d4-ex14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장의 오류 2곳(mail, until)을 바르게 고쳐 완전한 영어 문장으로 다시 쓰세요.`,stimulusEn:`오류 문장: Please check my mail and reply until tomorrow noon.`,answer:`Please check my email and reply by tomorrow noon.`,acceptableAlt:[`Please check my email and reply by noon tomorrow.`],explanationKo:`① mail → email, ② 완료 데드라인이므로 until → by로 고칩니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: Let’s discuss about the schedule until EOD. (오류 2곳: about 삭제, 전치사 교정)`,stimulusEn:`바른 문장 전체를 작성하세요.`,answer:`Let's discuss the schedule by EOD.`,explanationKo:`discuss 뒤 about을 빼고 마감 전치사 by EOD를 씁니다.`}},{id:`d4-ex15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`사전 공지 한영 영작`,questionKo:`다음 우리말을 give you a quick heads-up을 활용하여 자연스럽게 영작하세요.`,stimulusEn:`우리말: 서버 점검에 대해 미리 짧게 귀띔해 드리고 싶었습니다.
(힌트: I just wanted to / give you a quick heads-up / about the server maintenance.)`,answer:`I just wanted to give you a quick heads-up about the server maintenance.`,explanationKo:`I just wanted to give you a quick heads-up about [주제] 패턴을 통째로 체화해 두세요.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "현재 디자인 검토가 가장 큰 병목 구간입니다." (Design review / is the main bottleneck / right now.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Design review is the main bottleneck right now.`,explanationKo:`지연 지점을 명확히 짚어주는 실무 표현입니다.`}}],tutorScenario:{openingQuestionEn:`Quick check-in! How is your current project coming along, and when do you think you can wrap up the first draft?`,openingQuestionKo:`짧게 진행 상황 체크할게요! 지금 맡으신 작업은 순조로운가요? 초안은 언제쯤 마무리해서 공유해주실 수 있을까요?`,followUpQuestionEn:`Sounds good! Is there any bottleneck I should be aware of, or anyone else we should loop in before final sign-off?`,followUpQuestionKo:`좋네요! 혹시 제가 미리 알아둘 병목 이슈가 있거나, 최종 승인 전에 함께 초대해야 할 담당자가 있을까요?`,recommendedChunks:[`right on track`,`wrap up ~ by Friday`,`keep you in the loop`,`give you a heads-up`,`loop in ~`],modelAnswerEn:`Everything is right on track! I'll wrap up the first draft by EOD Thursday and keep you in the loop. Just a quick heads-up—we'll need to loop in Legal so they can sign off on the terms.`}},a={dayNumber:5,weekNumber:1,cefrLevel:`a2`,dayBadge:`DAY 05 · 단답형 탈출 3문장 확장법`,categoryLabel:`오픽 IH·AL & 인터뷰·스몰토크 확장 기술`,title:`단답형 Yes/No 탈출: 3문장 스토리 확장`,subtitle:`질문을 받으면 어색하게 한마디로 끊기던 대화를 [핵심 포인트 → 이유 → 생생한 예시]로 매끄럽게 이어가는 법`,heroImage:`assets/scene_riverside_walk.jpg`,secondaryImage:`assets/scene_cafe_detour.jpg`,estimatedSprintMin:8,estimatedLectureMin:45,keyExpression:`What I love most is that it helps me clear my head`,keySentenceByTier:{a1:`I like walking by the river after work.`,a2:`I like walking by the river because it helps me relax after work.`,b1:`What I love most about evening walks is that they help me clear my head after a hectic day.`,b2:`Whenever I feel burned out from staring at screens all day, going for a walk along the river is my go-to way to unwind and clear my head.`,c1:`After hours of back-to-back calls, nothing resets my focus quite like taking a brisk walk along the Han River and listening to the city wind down.`,c2:`When screen fatigue sets in after a relentless week, an unhurried riverside stroll remains my ultimate sanctuary for decompressing and regaining perspective.`},youtubeVideo:e[5],readingPassage:{titleEn:`Breaking the One-Word Answer Habit in English Conversations`,titleKo:`영어 대화에서 어색한 단답형 습관을 깨는 3문장 공식`,genreBadge:`스피킹 코칭 칼럼 · Lv.2–3`,estimatedMin:6,paragraphsEn:[`When someone asks "How was your weekend?", many learners freeze and reply with a single word: "Good." Although polite, one-word answers put all the pressure back on the other speaker to keep the conversation alive.`,`A simple three-sentence structure solves this instantly: start with your main point, add one short reason, and finish with a vivid personal detail. For instance, you can say you spent Saturday walking by the river, explain that it helps you clear your head, and mention the iced coffee you grabbed afterward.`,`Notice that you do not need rare academic vocabulary to sound fluent. Everyday connectors like "What I love most is...", "Whenever I feel...", and "Especially after..." turn basic words into warm, memorable stories.`],paragraphsSlash:[`When someone asks "How was your weekend?", / many learners freeze / and reply with a single word: "Good." / Although polite, / one-word answers put all the pressure back on the other speaker / to keep the conversation alive.`,`A simple three-sentence structure solves this instantly: / start with your main point, / add one short reason, / and finish with a vivid personal detail. / For instance, you can say you spent Saturday walking by the river, / explain that it helps you clear your head, / and mention the iced coffee you grabbed afterward.`,`Notice that you do not need rare academic vocabulary / to sound fluent. / Everyday connectors like "What I love most is...", "Whenever I feel...", and "Especially after..." / turn basic words into warm, memorable stories.`],paragraphsKo:[`누군가 “주말 잘 보냈어요?”라고 물으면 많은 학습자가 얼어붙어 “Good” 한 마디로 답하곤 합니다. 예의는 갖췄지만 단답형 답변은 대화를 이어가야 할 부담을 상대방에게 모두 넘겨 버립니다.`,`단순한 3문장 구조로 이 문제를 바로 해결할 수 있습니다. 핵심 결론으로 시작해 짧은 이유를 덧붙이고, 생생한 개인 에피소드로 마무리하는 것입니다. 예를 들어 토요일에 강변을 걸었다고 말하고, 머리를 식히는 데 도움이 된다고 설명한 뒤, 끝나고 마신 아이스커피 이야기를 덧붙여 보세요.`,`유창하게 들리기 위해 어려운 학술 어휘가 필요한 것은 아닙니다. "What I love most is...", "Whenever I feel...", "Especially after..." 같은 일상 연결 표현만으로도 기초 단어가 따뜻하고 기억에 남는 이야기로 바뀝니다.`],keyExpressions:[`clear my head`,`three-sentence structure`,`What I love most is`,`unwind`,`vivid detail`],comprehensionQuiz:[{id:`d5-rq01`,questionKo:`단답형 답변("Good.")이 영어 대화에서 아쉬운 이유는 무엇인가요?`,options:[`문법적으로 완전히 틀린 표현이기 때문`,`대화를 이어가야 하는 부담을 상대방에게 모두 넘기기 때문`,`발음이 너무 어렵기 때문`],answer:`대화를 이어가야 하는 부담을 상대방에게 모두 넘기기 때문`,explanationKo:`첫 문단 "put all the pressure back on the other speaker to keep the conversation alive"가 근거입니다.`},{id:`d5-rq02`,questionKo:`본문이 제안하는 3문장 확장 구조의 올바른 순서는?`,options:[`핵심 결론 → 짧은 이유 → 생생한 개인 디테일`,`어려운 명언 → 문법 설명 → 질문하기`,`날씨 이야기 → 뉴스 요약 → 인사하기`],answer:`핵심 결론 → 짧은 이유 → 생생한 개인 디테일`,explanationKo:`둘째 문단 "start with your main point, add one short reason, and finish with a vivid personal detail"을 확인하세요.`},{id:`d5-rq03`,questionKo:`본문이 유창함을 위해 강조한 요소는 무엇인가요?`,options:[`어려운 학술 단어만 골라 쓰기`,`"What I love most is..." 같은 일상 연결 표현으로 스토리 확장하기`,`최대한 빠르게 10초 안에 말 끝내기`],answer:`"What I love most is..." 같은 일상 연결 표현으로 스토리 확장하기`,explanationKo:`셋째 문단에서 일상 연결어(everyday connectors)의 힘을 강조하고 있습니다.`}]},vocabList:[{id:`d5-v01`,word:`What I love most is ~`,phonetic:`/wʌt aɪ lʌv moʊst ɪz/`,pos:`강조 구문`,meaningKo:`제가 가장 좋아하는 점은 바로 ~입니다`,meaningEn:`the best or favorite aspect for me is ~`,nuanceTipKo:`밋밋한 "I like ~" 대신 문두에 What절 명사구를 세우면 듣는 사람의 귀가 번쩍 뜨이는 원어민 인트로가 됩니다.`,exampleEn:`What I love most about this neighborhood is how quiet it is.`,exampleKo:`이 동네에서 제가 가장 좋아하는 점은 정말 조용하다는 거예요.`},{id:`d5-v02`,word:`clear my head`,phonetic:`/klɪr maɪ hed/`,pos:`관용구`,meaningKo:`복잡한 머리를 식히다, 잡념을 비우다`,meaningEn:`stop worrying and refresh your thoughts`,nuanceTipKo:`한국인들이 흔히 "refresh my brain"이라고 콩글리시를 만들곤 하는데, 영어권에서는 clear my head를 압도적으로 많이 씁니다!`,exampleEn:`A 20-minute walk always helps me clear my head.`,exampleKo:`20분 정도 산책하면 늘 복잡한 머리를 식히는 데 도움이 돼요.`},{id:`d5-v03`,word:`unwind`,phonetic:`/ˌʌnˈwaɪnd/`,pos:`동사`,meaningKo:`(하루의 긴장·피로를) 풀다, 쉬다`,meaningEn:`relax after a period of work or tension`,nuanceTipKo:`태엽(wind)이 팽팽히 감긴 상태를 풀어준다(un-wind)는 어원! 퇴근 후 휴식을 말할 때 relax보다 훨씬 세련됩니다.`,exampleEn:`Listening to jazz is my favorite way to unwind at night.`,exampleKo:`밤에 재즈를 듣는 것이 제가 제일 좋아하는 피로 해소법이에요.`},{id:`d5-v04`,word:`hectic`,phonetic:`/ˈhektɪk/`,pos:`형용사`,meaningKo:`정신없이 바쁜, 눈코 뜰 새 없는`,meaningEn:`full of frantic, nonstop activity`,nuanceTipKo:`busy day 대신 hectic day / hectic week를 쓰면 오픽·인터뷰 어휘 점수가 즉각 올라갑니다.`,exampleEn:`After a hectic week, I just want to stay in.`,exampleKo:`정신없이 바쁜 한 주를 보낸 뒤엔 그냥 집에 콕 박혀 있고 싶어요.`},{id:`d5-v05`,word:`go-to`,phonetic:`/ˈɡoʊ tuː/`,pos:`형용사`,meaningKo:`(고민 없이) 늘 즐겨 찾는, 믿고 선택하는 ("최애/단골")`,meaningEn:`regularly chosen and relied upon as the best option`,nuanceTipKo:`my favorite 대신 my go-to cafe / my go-to stress reliever라고 해보세요. 완전히 현업 원어민 어감입니다.`,exampleEn:`Han River Park is my go-to spot whenever I need fresh air.`,exampleKo:`바깥공기가 필요할 때마다 제가 늘 찾는 단골 장소는 한강공원이에요.`},{id:`d5-v06`,word:`recharge my batteries`,phonetic:`/ˌriːˈtʃɑːrdʒ maɪ ˈbætəriz/`,pos:`관용구`,meaningKo:`에너지를 재충전하다`,meaningEn:`rest and regain energy and enthusiasm`,nuanceTipKo:`한국어 "힐링하다"를 "do healing"으로 쓰면 콩글리시입니다! 영어로는 unwind나 recharge (my batteries)로 표현하세요.`,exampleEn:`Weekend hikes really help me recharge my batteries.`,exampleKo:`주말 등산은 에너지를 재충전하는 데 정말 큰 도움이 됩니다.`},{id:`d5-v07`,word:`for instance`,phonetic:`/fɔːr ˈɪnstəns/`,pos:`연결부사구`,meaningKo:`예를 들어 (구체적 에피소드 연결)`,meaningEn:`for example; as a specific illustration`,nuanceTipKo:`2번째 문장(이유)에서 3번째 문장(실제 경험담)으로 넘어갈 때 말을 자연스럽게 이어주는 최고의 윤활유입니다.`,exampleEn:`For instance, just last night I walked two miles along the stream.`,exampleKo:`예를 들어 바로 어젯밤에도 천변을 따라 2마일이나 걸었거든요.`},{id:`d5-v08`,word:`go for a walk`,phonetic:`/ɡoʊ fɔːr ə wɔːk/`,pos:`연어(Collocation)`,meaningKo:`산책하러 가다`,meaningEn:`take a pleasant walk outside for leisure`,nuanceTipKo:`단순 이동(walk)이 아니라 기분 전환 삼아 걷는 산책은 go for a walk 또는 take a stroll을 씁니다.`,exampleEn:`The weather is gorgeous—let's go for a walk after lunch.`,exampleKo:`날씨가 정말 환상적이네요. 점심 먹고 산책하러 가요.`},{id:`d5-v09`,word:`burned out`,phonetic:`/bɜːrnd aʊt/`,pos:`형용사구`,meaningKo:`번아웃이 온, 심신이 소진된`,meaningEn:`exhausted physically and mentally from prolonged stress`,nuanceTipKo:`단순히 잠이 부족한 tired를 넘어 에너지가 고갈된 상태를 설명할 때 정확히 들어맞습니다.`,exampleEn:`Taking short breaks keeps me from feeling burned out.`,exampleKo:`짧게라도 휴식을 챙겨야 번아웃이 오는 걸 막을 수 있어요.`},{id:`d5-v10`,word:`stay in`,phonetic:`/steɪ ɪn/`,pos:`구동사`,meaningKo:`외출하지 않고 집에서 쉬다 ("집콕하다")`,meaningEn:`remain at home rather than going out socially`,nuanceTipKo:`go out(외출해 놀다)의 정반대 구동사! "집순이/집돌이"인 주말 루틴을 말할 때 필수입니다.`,exampleEn:`Do you feel like going out tonight, or would you rather stay in?`,exampleKo:`오늘 밤에 나가서 놀고 싶어, 아니면 그냥 집에서 쉬고 싶어?`},{id:`d5-v11`,word:`take my mind off ~`,phonetic:`/teɪk maɪ maɪnd ɔːf/`,pos:`관용구`,meaningKo:`~에 대한 걱정·생각을 잠시 잊게 해주다`,meaningEn:`stop you from thinking or worrying about something stressful`,nuanceTipKo:`취미 활동을 왜 좋아하는지 이유를 댈 때 "It takes my mind off work(일 생각을 잊게 해줘요)"라고 쓰면 만점 답변입니다!`,exampleEn:`Cooking dinner really takes my mind off work stress.`,exampleKo:`저녁 요리를 하면 업무 스트레스 생각을 싹 잊게 돼요.`},{id:`d5-v12`,word:`a breath of fresh air`,phonetic:`/ə breθ əv freʃ er/`,pos:`관용구`,meaningKo:`신선한 활력소, 기분 전환`,meaningEn:`a refreshing change from routine`,nuanceTipKo:`실제 상쾌한 바깥공기뿐 아니라 반복되는 일상 속 신선한 변화를 비유할 때도 자주 씁니다.`,exampleEn:`Getting away from the city was a real breath of fresh air.`,exampleKo:`도심을 잠시 벗어난 것이 정말 신선한 활력소가 되었어요.`},{id:`d5-v13`,word:`on top of that`,phonetic:`/ɑːn tɑːp əv ðæt/`,pos:`연결부사구`,meaningKo:`게다가, 그뿐만 아니라 (장점 추가)`,meaningEn:`in addition to what was just mentioned`,nuanceTipKo:`딱딱한 Moreover, Furthermore 대신 구어체 스피킹에서 두 번째 장점을 덧붙일 때 가장 자연스럽습니다.`,exampleEn:`It's free, and on top of that, I sleep much better afterward.`,exampleKo:`돈도 안 들고, 게다가 다녀오면 잠도 훨씬 푹 잘 자요.`},{id:`d5-v14`,word:`stare at a screen`,phonetic:`/ster æt ə skriːn/`,pos:`연어(Collocation)`,meaningKo:`모니터/스마트폰 화면을 뚫어져라 쳐다보다`,meaningEn:`look fixedly at a computer or phone display for a long time`,nuanceTipKo:`현대 직장인·학생이 야외 취미를 즐기는 배경 이유로 대기에 가장 공감 가는 표현입니다.`,exampleEn:`After staring at a screen for eight hours, my eyes need a rest.`,exampleKo:`8시간 내내 모니터 화면만 쳐다보고 나면 눈을 쉬게 해줘야 해요.`},{id:`d5-v15`,word:`make a habit of -ing`,phonetic:`/meɪk ə ˈhæbɪt əv/`,pos:`관용구`,meaningKo:`~하는 것을 습관화하다(루틴으로 삼다)`,meaningEn:`regularly and intentionally do something as a routine`,nuanceTipKo:`스피킹 답변의 마지막 3번째 마무리 문장으로 "그래서 요즘 매일 ~하는 습관을 들이고 있어요"라고 맺기 좋습니다.`,exampleEn:`Lately, I've made a habit of walking 30 minutes after dinner.`,exampleKo:`요즘은 저녁 식사 후 30분씩 걷는 것을 습관으로 만들고 있어요.`}],dialogue:[{id:`d5-t1`,speaker:`Interviewer`,roleLabel:`글로벌 캐주얼 티타임 호스트`,voicePitch:.94,sceneImage:`assets/scene_riverside_walk.jpg`,cameraMotion:`zoom-in`,english:`Chloe, your team has been super busy lately! How do you usually unwind after a hectic workday?`,slashBroken:`Chloe, / your team has been super busy lately! / How do you usually unwind / after a hectic workday?`,korean:`클로이, 요즘 팀이 엄청 바빴잖아요! 정신없는 하루 일과를 마친 뒤엔 주로 어떻게 피로를 푸세요?`,keyHighlight:`unwind after a hectic workday`,noteKo:`스몰토크·인터뷰·오픽에서 100% 등장하는 단골 질문입니다. 단답형("I just walk.") 대신 3문장으로 풀어내 보세요!`},{id:`d5-t2`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_riverside_walk.jpg`,cameraMotion:`pan-right`,english:`My go-to way to unwind is going for an evening walk along the Han River near my apartment.`,slashBroken:`My go-to way to unwind / is going for an evening walk / along the Han River / near my apartment.`,korean:`[1문장: 핵심 결론] 제가 제일 즐겨 찾는 피로 해소법은 집 근처 한강 변을 따라 저녁 산책을 나가는 거예요.`,keyHighlight:`My go-to way to unwind`,noteKo:`PREP의 P(Point): My go-to way to unwind is ~ 패턴으로 명확하고 세련되게 첫 문장을 엽니다.`},{id:`d5-t3`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_riverside_walk.jpg`,cameraMotion:`pan-left`,english:`What I love most about it is that the river breeze takes my mind off work and clears my head.`,slashBroken:`What I love most about it is that / the river breeze takes my mind off work / and clears my head.`,korean:`[2문장: 이유·매력] 가장 좋은 점은 강바람을 쐬면 업무 생각을 잠시 잊고 복잡한 머리를 식힐 수 있다는 거예요.`,keyHighlight:`What I love most ~ clears my head`,noteKo:`PREP의 R(Reason): What I love most about it is that ~ 구문으로 왜 좋은지 감정과 효능을 덧붙입니다.`},{id:`d5-t4`,speaker:`Interviewer`,roleLabel:`글로벌 캐주얼 티타임 호스트`,voicePitch:.94,sceneImage:`assets/scene_riverside_walk.jpg`,cameraMotion:`zoom-in`,english:`That sounds amazing, especially after staring at a laptop screen all day! Do you walk alone or with someone?`,slashBroken:`That sounds amazing, / especially after staring at a laptop screen all day! / Do you walk alone or with someone?`,korean:`정말 좋겠네요, 특히 하루 종일 노트북 화면만 쳐다본 뒤에는요! 혼자 걸으시나요, 아니면 누구와 함께 걸으시나요?`,keyHighlight:`staring at a laptop screen all day`,noteKo:`상대방의 이유에 공감하며 자연스럽게 후속 질문(follow-up question)이 이어집니다.`},{id:`d5-t5`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_riverside_walk.jpg`,cameraMotion:`pan-right`,english:`Mostly on my own with an acoustic playlist! For instance, last night I walked until sunset and felt totally recharged.`,slashBroken:`Mostly on my own / with an acoustic playlist! / For instance, last night / I walked until sunset and felt totally recharged.`,korean:`[3문장: 구체적 에피소드] 주로 어쿠스틱 음악을 들으며 혼자 걸어요! 예를 들어 어젯밤에도 노을 질 때까지 걸었더니 완전히 재충전됐어요.`,keyHighlight:`For instance, last night ~`,noteKo:`PREP의 E(Example): For instance + 어제/지난주 실제 장면 한 줄을 넣으면 살아 숨 쉬는 원어민 영어가 됩니다.`},{id:`d5-t6`,speaker:`Interviewer`,roleLabel:`글로벌 캐주얼 티타임 호스트`,voicePitch:.94,sceneImage:`assets/scene_cafe_detour.jpg`,cameraMotion:`zoom-in`,english:`I should definitely make a habit of doing that too instead of just staying in on my couch!`,slashBroken:`I should definitely make a habit of doing that too / instead of just staying in / on my couch!`,korean:`저도 소파에 누워 집콕만 하지 말고 꼭 그렇게 산책하는 습관을 들여야겠네요!`,keyHighlight:`make a habit of ~ staying in`,noteKo:`instead of 뒤에도 전치사의 목적어로 동명사(staying in)가 온다는 점을 함께 챙기세요.`}],grammarSections:[{title:`원리 01 · 어색한 침묵을 깨는 3문장 PREP 스피킹 엔진`,coreFormula:`① Point (My go-to ~ is...) → ② Reason (What I love most is that...) → ③ Example (For instance, last week...)`,wrongKonglish:`Q: What do you do after work? → A: Um... I walk. Because it is good.`,rightNative:`My go-to way to unwind is walking by the river. What I love most is that it clears my head. For instance, I walked an hour last night!`,explanationKo:`영어를 못해서 대화가 끊기는 게 아니라, 단답형으로 마침표를 빨리 찍어버려서 대화가 끊기는 것입니다. 어떤 질문을 받든 [① 내 최애 선택(go-to) → ② 가장 좋은 이유(What I love most) → ③ 어제·지난주 짧은 실례(For instance)] 3문장 템플릿에 얹으면 최소 30초 이상 유창하게 말할 수 있습니다.`,registerSpectrum:{casual:`I love evening walks! They really clear my head after a crazy day.`,standard:`My go-to way to unwind is going for a walk because it helps me clear my head.`,formal:`I make a habit of taking evening walks to recharge and maintain mental clarity.`}},{title:`원리 02 · 한국어 "힐링하다 / 리프레시하다" 콩글리시 완전 정복`,coreFormula:`unwind / clear my head / recharge my batteries / take my mind off work`,wrongKonglish:`Going to the park gives me many healings and refreshes my brain.`,rightNative:`Going to the park helps me unwind, clear my head, and recharge my batteries.`,explanationKo:`영어에서 heal은 "상처·골절·깊은 트라우마가 치유되다"라는 무거운 의학적·심리적 동사입니다! 한국어식 "주말에 카페 가서 힐링했어"를 "I did healing at a cafe"라고 하면 원어민이 "어디 다쳤었어?!"라며 깜짝 놀랍니다. 일상적인 스트레스 해소와 힐링은 반드시 unwind, relax, clear my head, recharge로 표현하세요.`,registerSpectrum:{casual:`A quiet cafe trip really helped me unwind this weekend.`,standard:`Spending time in nature helps me recharge my batteries.`,formal:`Taking regular time off is essential to prevent feeling burned out.`}},{title:`원리 03 · 문장 첫머리에 힘을 싣는 What 관계대명사 명사절 강조법`,coreFormula:`What I love most (about A) + is (that) + 주어 + 동사`,wrongKonglish:`The thing which I very like is river wind is cool.`,rightNative:`What I love most about it is that the river breeze feels so refreshing.`,explanationKo:`[What + 주어 + 동사]는 그 자체로 "~하는 것"이라는 단수 명사 덩어리 주어가 됩니다. 따라서 바로 뒤에 단수 동사 is를 연결하고, 설명할 내용이 문장이면 접속사 that + 완전한 문장을 이어 붙이면 고급스러운 강조 구문이 손쉽게 완성됩니다.`,registerSpectrum:{casual:`What I love most is just listening to music while I walk.`,standard:`What I love most about this cafe is that it stays quiet at night.`,formal:`What we value most in our team culture is open communication.`}}],sprintDrills:[{id:`d5-s01`,drillType:`chunk-build`,promptKo:`제가 가장 좋아하는 피로 해소법은 저녁 산책을 나가는 거예요.`,promptEnHint:`My go-to way to unwind is ~ 패턴으로 시작하세요.`,targetEn:`My go-to way to unwind is going for an evening walk.`,chunks:[`My go-to way`,`to unwind`,`is going for`,`an evening walk.`],explanationKo:`go-to(~할 때 늘 찾는 단골 선택)와 unwind(긴장을 풀다)를 결합한 만점 오프닝입니다.`},{id:`d5-s02`,drillType:`konglish-fix`,promptKo:`"주말 등산으로 제대로 힐링(재충전)했어요!" — 자연스러운 영어는?`,promptEnHint:`do healing 콩글리시를 피하세요!`,targetEn:`Hiking this weekend really helped me unwind and recharge.`,wrongKonglishOption:`Hiking this weekend really made me do healing a lot.`,explanationKo:`한국어 "힐링하다"는 영어에서 unwind와 recharge (my batteries)로 표현합니다.`},{id:`d5-s03`,drillType:`chunk-build`,promptKo:`제가 가장 좋아하는 점은 그것이 복잡한 머리를 식혀준다는 거예요.`,promptEnHint:`강조 주어 What I love most is that ~ 을 조립하세요.`,targetEn:`What I love most is that it clears my head.`,chunks:[`What I love most`,`is that`,`it clears`,`my head.`],explanationKo:`What절은 단수 취급하므로 동사 is를 쓰고, clear my head로 마무리합니다.`},{id:`d5-s04`,drillType:`active-blank`,promptKo:`정신없이 바쁜 하루 일과를 마친 뒤엔 그냥 집에서 쉬고 싶어요.`,promptEnHint:`눈코 뜰 새 없이 바쁜(h로 시작하는 형용사)을 넣으세요.`,targetEn:`After a hectic workday, I just want to stay in.`,blankData:{before:`After a`,answer:`hectic`,after:`workday, I just want to stay in.`,firstLetterHint:`h_____ (6글자)`},explanationKo:`hectic workday와 stay in(집콕하다)은 함께 쓰기 아주 좋은 짝꿍입니다.`},{id:`d5-s05`,drillType:`active-blank`,promptKo:`저녁 요리를 하면 업무 스트레스 생각을 싹 잊게 돼요.`,promptEnHint:`take my ____ off ~ (생각을 다른 곳으로 돌리다)`,targetEn:`Cooking dinner really takes my mind off work stress.`,blankData:{before:`Cooking dinner really takes my`,answer:`mind`,after:`off work stress.`,firstLetterHint:`m___ (4글자)`},explanationKo:`take one’s mind off ~ 는 걱정거리에서 주의를 환기시켜 준다는 핵심 숙어입니다.`},{id:`d5-s06`,drillType:`konglish-fix`,promptKo:`"하루 종일 모니터 화면을 쳐다본 뒤라 눈이 피곤해요."`,promptEnHint:`화면을 응시하다는 전치사 결합을 확인하세요.`,targetEn:`My eyes are tired after staring at a screen all day.`,wrongKonglishOption:`My eyes are tired after staring to a screen all day.`,explanationKo:`stare는 반드시 전치사 at과 결합하여 stare at a screen으로 씁니다.`},{id:`d5-s07`,drillType:`chunk-build`,promptKo:`예를 들어 바로 어젯밤에도 강변을 따라 한 시간 동안 걸었어요.`,promptEnHint:`예시 연결어 For instance로 문장을 여세요.`,targetEn:`For instance, just last night I walked along the river for an hour.`,chunks:[`For instance,`,`just last night`,`I walked along the river`,`for an hour.`],explanationKo:`구체적인 과거 시점(just last night) 에피소드를 한 줄 넣으면 스피킹 설득력이 극대화됩니다.`},{id:`d5-s08`,drillType:`active-blank`,promptKo:`짧은 휴식을 챙겨야 번아웃이 오는 것을 막을 수 있어요.`,promptEnHint:`에너지가 다 타버려 소진된(b_____ out)에서 앞 단어를 쓰세요.`,targetEn:`Taking short breaks keeps me from feeling burned out.`,blankData:{before:`Taking short breaks keeps me from feeling`,answer:`burned`,after:`out.`,firstLetterHint:`b_____ (6글자)`},explanationKo:`feel burned out은 심신이 지쳐 소진된 번아웃 상태를 뜻합니다.`},{id:`d5-s09`,drillType:`chunk-build`,promptKo:`돈도 안 들고, 게다가 다녀오면 잠도 훨씬 잘 자요.`,promptEnHint:`구어체 추가 연결어 on top of that을 넣으세요.`,targetEn:`It's free, and on top of that, I sleep much better.`,chunks:[`It's free,`,`and on top of that,`,`I sleep`,`much better.`],explanationKo:`비교급 강조 부사 much(more better 금지!)와 on top of that을 자연스럽게 연결합니다.`},{id:`d5-s10`,drillType:`active-blank`,promptKo:`요즘 저녁 식사 후 30분씩 걷는 습관을 들이고 있어요.`,promptEnHint:`make a _____ of -ing (~하는 습관을 들이다)`,targetEn:`Lately, I've made a habit of walking 30 minutes after dinner.`,blankData:{before:`Lately, I've made a`,answer:`habit`,after:`of walking 30 minutes after dinner.`,firstLetterHint:`h____ (5글자)`},explanationKo:`make a habit of + 동명사(-ing)는 일상 루틴을 소개할 때 최고의 마무리 구문입니다.`}],worksheetExam:[{id:`d5-ex01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`관용구 clear my head`,questionKo:`빈칸에 알맞은 명사(1단어)를 넣어 "신선한 밤공기가 복잡한 머리를 식히는 데 도움이 된다"를 완성하세요.`,stimulusEn:`Stepping outside for fresh night air always helps me clear my __________.`,answer:`head`,acceptableAlt:[`mind`],explanationKo:`clear my head(또는 mind)는 복잡한 잡념을 비우고 머리를 맑게 식힌다는 뜻입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "업무 걱정을 잠시 잊게 해주다"가 되도록 빈칸(2단어)을 채우세요.`,stimulusEn:`Playing tennis really takes my __________ __________ work.`,answer:`mind off`,explanationKo:`take one’s mind off ~ 숙어입니다.`}},{id:`d5-ex02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`피로 해소 unwind`,questionKo:`빈칸에 알맞은 동사(1단어)를 넣어 "긴 하루 끝에 긴장과 피로를 풀다"를 완성하세요.`,stimulusEn:`Drinking warm chamomile tea is how I __________ at the end of a long day.`,answer:`unwind`,acceptableAlt:[`relax`],explanationKo:`하루 동안 쌓인 긴장의 태엽을 풀어준다는 뜻의 unwind가 가장 세련된 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "늘 즐겨 찾는 단골 카페"가 되도록 하이픈(-)을 포함한 형용사(1단어)를 쓰세요.`,stimulusEn:`This quiet roastery is my __________ cafe for weekend reading.`,answer:`go-to`,explanationKo:`고민 없이 믿고 찾는 최애 선택지를 my go-to + 명사로 표현합니다.`}},{id:`d5-ex03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`형용사 hectic`,questionKo:`빈칸에 알맞은 형용사(1단어)를 넣어 "정신없이 바빴던 한 주"를 완성하세요.`,stimulusEn:`After such a __________ week at the office, I slept until noon on Saturday.`,answer:`hectic`,explanationKo:`눈코 뜰 새 없이 분주한 일정을 묘사할 때 hectic을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "외출하지 않고 집에서 쉬다(집콕하다)" 구동사(2단어)를 넣으세요.`,stimulusEn:`It's pouring outside, so let's just __________ __________ tonight.`,answer:`stay in`,explanationKo:`외출(go out) 대신 집에 머물며 쉬는 것은 stay in입니다.`}},{id:`d5-ex04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`관용구 recharge batteries`,questionKo:`빈칸에 알맞은 동사(1단어)를 넣어 "주말 여행이 에너지를 재충전하는 데 도움이 됐다"를 완성하세요.`,stimulusEn:`A short trip to Gangneung helped me __________ my batteries.`,answer:`recharge`,explanationKo:`recharge one’s batteries는 지친 활력을 되찾는다는 대표적인 관용구입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "번아웃이 온(소진된) 느낌이 들다" 빈칸(2단어)을 채우세요.`,stimulusEn:`Working six weekends in a row left him feeling __________ __________.`,answer:`burned out`,explanationKo:`feel burned out 구문입니다.`}},{id:`d5-ex05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`습관 형성 make a habit of`,questionKo:`괄호 안 동사 stretch를 어법에 맞게 변형하여 "아침마다 스트레칭하는 습관을 들였다"를 완성하세요.`,stimulusEn:`I have made a habit of __________ (stretch) for ten minutes every morning.`,answer:`stretching`,explanationKo:`전치사 of의 목적어 자리이므로 동명사 stretching이 와야 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] instead of 뒤에 괄호 안 동사 take를 알맞게 변형해 쓰세요.`,stimulusEn:`I walked home instead of __________ (take) the crowded bus.`,answer:`taking`,explanationKo:`전치사구 instead of 뒤에도 동명사 taking을 씁니다.`}},{id:`d5-ex06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`What절 주어 수일치`,questionKo:`다음 빈칸에 들어갈 어법상 가장 올바른 표현은?`,stimulusEn:`____________________ about evening walks is how peaceful the streets feel.`,options:[`What I love most`,`That I love most`,`Which I love most`,`How I love most thing`],answer:`What I love most`,explanationKo:`선행사를 포함한 관계대명사 What(~하는 것)이 문장 맨 앞에서 명사절 주어를 이끕니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] What절 주어는 단수 취급합니다. 알맞은 현재형 be동사(1단어)를 넣으세요.`,stimulusEn:`What I enjoy most on weekends __________ cooking for friends.`,answer:`is`,explanationKo:`What절 주어는 단수 동사 is로 받습니다.`}},{id:`d5-ex07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`힐링 콩글리시 교정`,questionKo:`"주말에 숲속 펜션에 다녀왔더니 제대로 힐링이 되었어요"를 가장 원어민답게 영작한 문장은?`,stimulusEn:`healing 동사의 실제 영어 쓰임에 주의하여 고르세요.`,options:[`Staying at a forest cabin gave me big healing.`,`I did healing very well at a forest cabin this weekend.`,`Staying at a forest cabin was a breath of fresh air and helped me recharge.`,`The forest cabin cured my weekend stress disease.`],answer:`Staying at a forest cabin was a breath of fresh air and helped me recharge.`,explanationKo:`a breath of fresh air(신선한 기분 전환)와 helped me recharge를 결합하면 최고급 원어민 표현이 됩니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "신선한 활력소/기분 전환"을 뜻하는 관용구에서 빈칸(2단어)을 채우세요.`,stimulusEn:`Getting out of town was a breath of __________ __________.`,answer:`fresh air`,explanationKo:`a breath of fresh air 관용구입니다.`}},{id:`d5-ex08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`비교급 강조 부사`,questionKo:`다음 빈칸에 들어갈 수 **없는** 단어는?`,stimulusEn:`After walking for 30 minutes, I always sleep __________ better at night.`,options:[`much`,`way`,`far`,`more`],answer:`more`,explanationKo:`better는 이미 비교급이므로 앞에 more를 또 붙이면(more better) 문법 오류입니다! 비교급 강조는 much, even, far, a lot, (구어체) way를 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 문장 "I feel more better now."에서 more를 대신할 4글자 강조 부사(m으로 시작)를 쓰세요.`,stimulusEn:`I feel __________ better now.`,answer:`much`,explanationKo:`much better가 올바른 표현입니다.`}},{id:`d5-ex09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`담화 연결어 기능`,questionKo:`앞 문장에서 장점을 말한 뒤, 두 번째 장점을 "게다가, 그뿐만 아니라"라며 구어체로 자연스럽게 덧붙일 때 쓰는 표현은?`,stimulusEn:`Walking doesn't cost a dime, and ____________________, it boosts my mood.`,options:[`on top of that`,`at the last minute`,`on my way home`,`by the end of day`],answer:`on top of that`,explanationKo:`on top of that은 그 위에 하나를 더 얹듯 추가 장점을 덧붙일 때 쓰는 최고의 스피킹 연결어입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 구체적 사례를 들며 "예를 들어"를 뜻하는 2단어 표현(For i_______)을 완성하세요.`,stimulusEn:`__________ __________, just yesterday I walked five kilometers.`,answer:`For instance`,explanationKo:`For example과 함께 교차해 쓰기 좋은 For instance입니다.`}},{id:`d5-ex10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`산책 연어 표현`,questionKo:`"점심 먹고 잠깐 산책하러 갈래요?"를 뜻하는 가장 자연스러운 영어 문장은?`,stimulusEn:`여가·기분 전환 산책을 나타내는 연어를 고르세요.`,options:[`Do you want to go for a walk after lunch?`,`Do you want to run errands foot after lunch?`,`Shall we do walking road after lunch?`,`Want to step street after lunch?`],answer:`Do you want to go for a walk after lunch?`,explanationKo:`go for a walk(또는 take a walk)가 산책하러 가다의 정확한 연어입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "노트북 화면을 뚫어져라 쳐다보다"에서 알맞은 전치사(1단어)를 넣으세요.`,stimulusEn:`My neck hurts from staring __________ my laptop screen.`,answer:`at`,explanationKo:`응시 대상을 가리킬 때 stare at을 씁니다.`}},{id:`d5-ex11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`PREP 1문장 go-to 오프닝 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 스피킹 첫 문장을 완성하세요.`,stimulusEn:`[ going for a walk / My go-to way / along the river. / to unwind / is ]`,answer:`My go-to way to unwind is going for a walk along the river.`,explanationKo:`[주어부] My go-to way to unwind + [동사] is + [보어] going for a walk along the river.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "제가 가장 즐겨 찾는 스트레스 해소법은 재즈 음악을 듣는 거예요." (My go-to way to unwind / is listening to / jazz music.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`My go-to way to unwind is listening to jazz music.`,explanationKo:`보어 자리에 본인의 실제 취미 동명사구만 넣으면 내 답변이 완성됩니다!`}},{id:`d5-ex12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`What절 강조 구문 배열`,questionKo:`주어진 청크를 배열하여 이유를 설명하는 두 번째 문장을 완성하세요.`,stimulusEn:`[ my head. / What I love most / is that / about it / it clears ]`,answer:`What I love most about it is that it clears my head.`,explanationKo:`What I love most about it + is that + 주어(it) + 동사(clears my head) 구조입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이 카페에서 제가 가장 좋아하는 점은 밤에 조용하다는 거예요." (What I love most / about this cafe / is that / it is quiet at night.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`What I love most about this cafe is that it is quiet at night.`,explanationKo:`장소 묘사 오픽·일상 대화에서 즉시 쓸 수 있는 만능 문장입니다.`}},{id:`d5-ex13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`take my mind off 영작`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용하여 문장을 완성하세요.`,stimulusEn:`우리말: 요리를 하면 업무 스트레스에 대한 생각을 잊게 돼요.
(힌트: Cooking / really takes my mind off / work stress.)`,answer:`Cooking really takes my mind off work stress.`,explanationKo:`동명사 주어 Cooking은 단수 취급하므로 동사에 -s(takes)를 꼭 붙입니다!`,twinClinic:{questionKo:`[쌍둥이 클리닉] "달리기를 하면 복잡한 걱정을 잊게 돼요." (Running / takes my mind off / my worries.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Running takes my mind off my worries.`,explanationKo:`단수 동사 takes 수일치를 유지합니다.`}},{id:`d5-ex14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장의 오류 2곳(more better, do healing)을 고쳐 자연스러운 문장으로 쓰세요.`,stimulusEn:`오류 문장: Walking makes me feel more better and helps me do healing.`,answer:`Walking makes me feel much better and helps me unwind.`,acceptableAlt:[`Walking makes me feel much better and helps me recharge.`,`Walking makes me feel way better and helps me unwind.`],explanationKo:`more better → much better, do healing → unwind(또는 recharge)로 교정합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: What I like most are walking at night. (수일치 오류 1곳 교정)`,stimulusEn:`바른 문장 전체를 작성하세요.`,answer:`What I like most is walking at night.`,explanationKo:`What절 주어는 단수 동사 is로 받아야 합니다.`}},{id:`d5-ex15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`루틴 마무리 문장 영작`,questionKo:`다음 우리말을 make a habit of를 활용하여 자연스러운 현재완료 문장으로 작성하세요.`,stimulusEn:`우리말: 요즘은 저녁 식사 후 30분씩 걷는 습관을 들이고 있어요.
(힌트: Lately, / I have made a habit of / walking 30 minutes / after dinner.)`,answer:`Lately, I have made a habit of walking 30 minutes after dinner.`,acceptableAlt:[`Lately, I've made a habit of walking 30 minutes after dinner.`],explanationKo:`Lately(최근 들어)와 현재완료(have made a habit of -ing)의 결합이 아주 자연스럽습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "자기 전에 책을 읽는 습관을 들이려고 노력 중이에요." (I am trying to / make a habit of / reading before bed.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I am trying to make a habit of reading before bed.`,explanationKo:`make a habit of + 동명사 reading 구조를 완성합니다.`}}],tutorScenario:{openingQuestionEn:`After a hectic week of work or study, what is your go-to way to unwind and clear your head? Try answering in 2–3 full sentences!`,openingQuestionKo:`정신없이 바쁜 한 주를 보낸 뒤, 가장 즐겨 찾는 나만의 피로 해소법(힐링 루틴)은 무엇인가요? 단답형 대신 2~3문장으로 길게 답해보세요!`,followUpQuestionEn:`That sounds so refreshing! Could you share a quick example from this past week or weekend when you actually did that?`,followUpQuestionKo:`정말 상쾌하겠네요! 혹시 지난주나 주말에 실제로 그렇게 쉬셨던 구체적인 에피소드 한 줄을 덧붙여 주실 수 있나요?`,recommendedChunks:[`My go-to way to unwind is ~`,`What I love most is that ~`,`clear my head`,`takes my mind off ~`,`For instance, ~`],modelAnswerEn:`My go-to way to unwind is visiting a quiet neighborhood cafe on Sunday mornings. What I love most about it is that reading with a warm latte takes my mind off work and clears my head. For instance, last Sunday I read half a novel there and felt completely recharged!`}},o={dayNumber:6,weekNumber:1,cefrLevel:`a2`,isWeeklyReview:!0,dayBadge:`DAY 06 · WEEK 1 주간 종합 성취도 평가`,categoryLabel:`Week 1 총정리 리허설 & 20문항 실전 모의고사`,title:`Week 1 실전 통합 리허설 & 종합 모의고사`,subtitle:`Day 01~05에서 배운 75개 핵심 구동사·전치사·비즈니스 조율·3문장 확장법을 하나의 실전 스토리와 20문항 평가로 완전 체화`,heroImage:`assets/office_sitcom_scene.jpg`,secondaryImage:`assets/visual_preposition_card.jpg`,estimatedSprintMin:10,estimatedLectureMin:48,keyExpression:`Week 1 Complete Mastery: Fluency × Nuance × Accuracy`,keySentenceByTier:{a1:`I will finish by 5 PM and stop by a cafe on my way home.`,a2:`I'll wrap this up by 5 PM and stop by a cafe on my way home.`,b1:`Tomorrow looks tight on my end, so I'll wrap up the draft by Friday and unwind with an evening walk.`,b2:`Although an urgent issue came up and we had to push our sync back, we're still on track to wrap everything up by EOD Friday.`,c1:`Even though an unexpected escalation forced us to reschedule our mid-week sync, the team rallied to stay on track for our Friday deadline.`,c2:`Notwithstanding a mid-week client escalation that compelled us to push back our sync, we pulled everything together ahead of Friday’s EOD cutoff.`},youtubeVideo:e[6],readingPassage:{titleEn:`One Week That Changed How Minjun Speaks at Work`,titleKo:`민준 씨의 오피스 영어를 바꾼 1주일의 실전 기록`,genreBadge:`Week 1 종합 리포트 · Lv.1–2`,estimatedMin:7,paragraphsEn:[`At the start of the week, Minjun still translated every Korean sentence word for word before speaking. Whenever his overseas manager asked a quick question, he paused too long and fell back on short "Yes" or "Okay" replies.`,`By Friday, a noticeable shift had taken place. When a design update came up unexpectedly on Wednesday, he smoothly replied that Thursday looked tight on his end and proposed a Friday morning sync instead. He then promised to wrap up the revised slides by EOD and keep the whole team in the loop.`,`On his way home Friday evening, Minjun stopped by his favorite cafe to grab an iced oat latte before walking along the river to unwind. For the first time, speaking English felt less like taking a grammar exam and more like having a real conversation.`],paragraphsSlash:[`At the start of the week, / Minjun still translated every Korean sentence word for word / before speaking. / Whenever his overseas manager asked a quick question, / he paused too long / and fell back on short "Yes" or "Okay" replies.`,`By Friday, / a noticeable shift had taken place. / When a design update came up unexpectedly on Wednesday, / he smoothly replied that Thursday looked tight on his end / and proposed a Friday morning sync instead. / He then promised to wrap up the revised slides by EOD / and keep the whole team in the loop.`,`On his way home Friday evening, / Minjun stopped by his favorite cafe / to grab an iced oat latte / before walking along the river to unwind. / For the first time, / speaking English felt less like taking a grammar exam / and more like having a real conversation.`],paragraphsKo:[`주 초만 해도 민준 씨는 말하기 전에 모든 한국어 문장을 단어 대 단어로 직역하곤 했습니다. 해외 매니저가 짧은 질문을 던질 때마다 너무 오래 멈칫거리다가 짧은 "Yes"나 "Okay"로만 대답했습니다.`,`금요일 무렵에는 눈에 띄는 변화가 생겼습니다. 수요일에 디자인 수정 건이 갑자기 생겼을 때, 그는 목요일은 제 쪽 일정이 빠듯하다고 자연스럽게 알리고 금요일 오전 싱크를 역제안했습니다. 이어서 퇴근 전까지 수정 슬라이드를 마무리해 팀 전체와 공유하겠다고 약속했습니다.`,`금요일 퇴근길에 민준 씨는 강변을 걸으며 긴장을 풀기 전 단골 카페에 들러 아이스 오트 라떼를 샀습니다. 처음으로 영어 말하기가 문법 시험이 아니라 진짜 대화처럼 느껴졌습니다.`],keyExpressions:[`word for word`,`came up unexpectedly`,`tight on his end`,`wrap up ~ by EOD`,`keep ~ in the loop`,`unwind`],comprehensionQuiz:[{id:`d6-rq01`,questionKo:`주 초에 민준 씨가 해외 매니저와 대화할 때 겪었던 어려움은 무엇인가요?`,options:[`한국어를 단어별로 직역하느라 멈칫거리고 단답형으로만 답했다`,`너무 빠르게 말해서 상대가 알아듣지 못했다`,`화상회의 프로그램 설치를 못 했다`],answer:`한국어를 단어별로 직역하느라 멈칫거리고 단답형으로만 답했다`,explanationKo:`첫 문단 "translated every Korean sentence word for word... fell back on short Yes or Okay replies"를 확인하세요.`},{id:`d6-rq02`,questionKo:`수요일에 갑작스러운 디자인 수정 건이 생겼을 때 민준 씨가 취한 대응은?`,options:[`무조건 야근해서 당일 끝내겠다고 답했다`,`목요일 일정이 빠듯하다고 알리고 금요일 오전 싱크를 역제안했다`,`다른 팀원에게 업무를 넘겼다`],answer:`목요일 일정이 빠듯하다고 알리고 금요일 오전 싱크를 역제안했다`,explanationKo:`둘째 문단 "Thursday looked tight on his end and proposed a Friday morning sync instead"가 정답입니다.`},{id:`d6-rq03`,questionKo:`본문에서 Week 1 핵심 표현들이 자연스럽게 녹아 있지 않은 것은?`,options:[`stop by + on his way home`,`wrap up + by EOD`,`on my way to home + until EOD`],answer:`on my way to home + until EOD`,explanationKo:`home 앞에는 to를 쓰지 않고, 마감 기한에는 until이 아니라 by를 써야 합니다!`}]},vocabList:[{id:`d6-v01`,word:`pull everything together`,phonetic:`/pʊl ˈevriθɪŋ təˈɡeðər/`,pos:`구동사 구문`,meaningKo:`(흩어진 자료·일정을) 하나로 잘 취합해 완성하다`,meaningEn:`organize different parts effectively into one finished result`,nuanceTipKo:`주간 마감 때 여러 팀의 결과물을 하나로 깔끔하게 모을 때 쓰는 실무 고급 표현입니다.`,exampleEn:`Thanks for pulling everything together on short notice.`,exampleKo:`촉박한 일정에도 모든 자료를 잘 취합해 주셔서 감사합니다.`},{id:`d6-v02`,word:`on short notice`,phonetic:`/ɑːn ʃɔːrt ˈnoʊtɪs/`,pos:`전치사구`,meaningKo:`갑작스러운 연락에도, 촉박한 통보에도`,meaningEn:`with very little advance warning or time to prepare`,nuanceTipKo:`급하게 잡힌 미팅에 참석해 준 동료에게 감사 인사할 때 빠지지 않는 표현입니다.`,exampleEn:`Sorry to ask you to hop on a call on such short notice.`,exampleKo:`이렇게 급하게 통화를 요청드려 죄송합니다.`},{id:`d6-v03`,word:`get back to ~`,phonetic:`/ɡet bæk tuː/`,pos:`구동사`,meaningKo:`~에게 (확인 후) 다시 연락하다, 회신하다`,meaningEn:`contact someone later with an answer or update`,nuanceTipKo:`circle back과 더불어 일상·이메일에서 가장 빈도 높게 쓰이는 회신 약속 표현입니다.`,exampleEn:`Let me double-check my schedule and get back to you by noon.`,exampleKo:`제 일정을 한 번 더 확인해보고 정오까지 회신드릴게요.`},{id:`d6-v04`,word:`double-check`,phonetic:`/ˌdʌbl ˈtʃek/`,pos:`동사`,meaningKo:`실수 없도록 재차 꼼꼼히 확인하다`,meaningEn:`verify something a second time to ensure accuracy`,nuanceTipKo:`단순 check보다 신중하고 꼼꼼한 프로의 태도를 보여주는 동사입니다.`,exampleEn:`I'll double-check the figures before sending the deck.`,exampleKo:`발표자료를 보내기 전에 수치를 한 번 더 꼼꼼히 확인할게요.`},{id:`d6-v05`,word:`catch up (with ~)`,phonetic:`/kætʃ ʌp/`,pos:`구동사`,meaningKo:`(밀린 일·근황 토크를) 따라잡다, 오랜만에 회포를 풀다`,meaningEn:`talk to someone about recent news; get up to date on work`,nuanceTipKo:`친구와 밀린 수다를 떨 때도("Let's catch up over coffee!"), 밀린 이메일을 처리할 때도("catch up on emails") 씁니다.`,exampleEn:`Let's grab coffee this Friday and catch up!`,exampleKo:`이번 주 금요일에 커피 한잔하면서 밀린 이야기 나누자!`},{id:`d6-v06`,word:`iron out`,phonetic:`/ˈaɪərn aʊt/`,pos:`구동사`,meaningKo:`(남은 자잘한 문제·이견을) 매끄럽게 해결하다`,meaningEn:`resolve remaining small problems or details`,nuanceTipKo:`구겨진 셔츠를 다리미(iron)로 펴듯, 출시 전 세부 이슈를 깔끔히 정리할 때 씁니다.`,exampleEn:`We just need to iron out a few minor bugs before launch.`,exampleKo:`출시 전에 사소한 버그 몇 가지만 매끄럽게 잡으면 됩니다.`},{id:`d6-v07`,word:`pay off`,phonetic:`/peɪ ɔːf/`,pos:`구동사`,meaningKo:`(노력·고생이) 결실을 맺다, 보람이 있다`,meaningEn:`produce good results after hard effort`,nuanceTipKo:`야근과 노력이 좋은 결과로 이어졌을 때 "All our hard work paid off!"라고 격려해 보세요.`,exampleEn:`Staying late to polish the demo really paid off.`,exampleKo:`데모를 다듬느라 늦게까지 남았던 노력이 진짜 빛을 발했어요.`},{id:`d6-v08`,word:`sleep in`,phonetic:`/sliːp ɪn/`,pos:`구동사`,meaningKo:`(알람 없이 주말 등에 일부러) 늦잠을 푹 자다`,meaningEn:`intentionally sleep later than usual in the morning`,nuanceTipKo:`실수로 지각 잠을 잔 oversleep과 달리, 휴일에 달콤하게 늦잠 자며 피로를 풀 때는 sleep in입니다!`,exampleEn:`I can't wait to sleep in this Saturday morning.`,exampleKo:`이번 주 토요일 아침엔 푹 늦잠 잘 생각에 벌써 설레네요.`},{id:`d6-v09`,word:`oversleep`,phonetic:`/ˌoʊvərˈsliːp/`,pos:`동사`,meaningKo:`(알람을 못 듣고 실수로) 늦잠 자서 늦다`,meaningEn:`sleep longer than intended by mistake`,nuanceTipKo:`출근·등교에 지각했을 때는 sleep in이 아니라 과거형 overslept("I overslept!")를 써야 합니다.`,exampleEn:`I accidentally overslept and missed the 8 AM express train.`,exampleKo:`실수로 늦잠을 자는 바람에 8시 급행열차를 놓쳤어요.`},{id:`d6-v10`,word:`treat myself to ~`,phonetic:`/triːt maɪˈself tuː/`,pos:`관용구`,meaningKo:`(고생한 나 자신에게) ~을 선물하다/대접하다`,meaningEn:`buy or do something special and enjoyable for yourself`,nuanceTipKo:`한 주를 열심히 달린 금요일 저녁, 맛있는 음식이나 디저트를 사 먹을 때 최고의 표현입니다.`,exampleEn:`I'm going to treat myself to a nice steak tonight.`,exampleKo:`오늘 저녁엔 고생한 저 자신에게 맛있는 스테이크를 대접할 거예요.`},{id:`d6-v11`,word:`ahead of schedule`,phonetic:`/əˈhed əv ˈskedʒuːl/`,pos:`전치사구`,meaningKo:`예정된 일정보다 앞서서 (조기 달성)`,meaningEn:`earlier than the planned time`,nuanceTipKo:`on track(예정대로)보다 한 단계 더 기분 좋은 표현! 반대로 일정보다 뒤처지면 behind schedule입니다.`,exampleEn:`Surprisingly, we wrapped up QA two days ahead of schedule.`,exampleKo:`놀랍게도 예정보다 이틀이나 앞서서 QA 테스트를 마무리했어요.`},{id:`d6-v12`,word:`behind schedule`,phonetic:`/bɪˈhaɪnd ˈskedʒuːl/`,pos:`전치사구`,meaningKo:`예정된 일정보다 뒤처진(지연된)`,meaningEn:`later than planned`,nuanceTipKo:`"일정이 조금 밀렸어요"는 "We are running a bit behind schedule"이라고 정중히 공유합니다.`,exampleEn:`We are running slightly behind schedule due to server issues.`,exampleKo:`서버 이슈로 인해 예정 일정보다 약간 지연되고 있습니다.`},{id:`d6-v13`,word:`keep ~ posted`,phonetic:`/kiːp ˈpoʊstɪd/`,pos:`관용구`,meaningKo:`~에게 새로운 소식을 계속 업데이트해 주다`,meaningEn:`regularly inform someone of the latest developments`,nuanceTipKo:`keep you in the loop와 100% 호환되는 친근하고 실용적인 표현입니다.`,exampleEn:`Keep me posted on how the client pitch goes!`,exampleKo:`클라이언트 발표가 어떻게 진행되는지 계속 소식 알려줘요!`},{id:`d6-v14`,word:`well-deserved`,phonetic:`/ˌwel dɪˈzɜːrvd/`,pos:`형용사`,meaningKo:`충분히 누릴 자격이 있는 (고생 끝에 마땅한)`,meaningEn:`rightly earned through hard work`,nuanceTipKo:`금요일 퇴근 인사나 휴가 가는 동료에게 "Have a well-deserved break!(고생 많았으니 푹 쉬어요!)"라고 건네보세요.`,exampleEn:`Enjoy your well-deserved weekend!`,exampleKo:`고생 많으셨으니 자격 충분한 꿀주말 보내세요!`},{id:`d6-v15`,word:`call an audible`,phonetic:`/kɔːl ən ˈɔːdəbl/`,pos:`실무 관용구`,meaningKo:`현장 상황에 맞춰 즉석에서 작전(계획)을 유연하게 바꾸다`,meaningEn:`change plans at the last minute in response to new conditions`,nuanceTipKo:`미식축구 쿼터백이 경기장에서 작전을 바꾸는 데서 유래한 북미 오피스 고급 표현입니다.`,exampleEn:`When the Wi-Fi died, we called an audible and used printed handouts.`,exampleKo:`와이파이가 끊기자마자 우리는 즉석에서 계획을 바꿔 인쇄 유인물로 진행했어요.`}],dialogue:[{id:`d6-t1`,speaker:`Marcus`,roleLabel:`디자인 리드`,voicePitch:.92,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Happy Friday, Chloe! Thanks again for hopping on that client call on such short notice earlier.`,slashBroken:`Happy Friday, Chloe! / Thanks again for hopping on that client call / on such short notice earlier.`,korean:`해피 프라이데이, 클로이! 아까 그렇게 급하게 요청했는데도 클라이언트 콜에 들어와 줘서 정말 고마워.`,keyHighlight:`on such short notice`,noteKo:`금요일 인사는 "Happy Friday!" 하나로 사무실 공기가 따뜻해집니다.`},{id:`d6-t2`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`pan-right`,english:`Anytime! I meant to wrap up my slides by noon, and pushing our internal sync back actually helped.`,slashBroken:`Anytime! / I meant to wrap up my slides by noon, / and pushing our internal sync back / actually helped.`,korean:`별말씀을! 정오까지 슬라이드를 마무리하려던 참이었는데, 내부 미팅을 뒤로 미룬 게 오히려 도움이 됐어.`,keyHighlight:`meant to wrap up ~ by noon / pushing ~ back`,noteKo:`Day 2(meant to), Day 3(push back), Day 4(wrap up ~ by) 핵심 표현이 한 문장 안에서 물 흐르듯 결합됩니다!`},{id:`d6-t3`,speaker:`Marcus`,roleLabel:`디자인 리드`,voicePitch:.92,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`pan-left`,english:`Working late on Tuesday really paid off—the client signed off on the whole proposal ahead of schedule!`,slashBroken:`Working late on Tuesday really paid off— / the client signed off on the whole proposal / ahead of schedule!`,korean:`화요일에 야근했던 보람이 제대로 있었어. 클라이언트가 예정보다 앞서서 제안서 전체를 최종 승인했잖아!`,keyHighlight:`paid off / signed off on / ahead of schedule`,noteKo:`Day 2(working late) + Day 6(paid off, ahead of schedule) + Day 4(signed off on) 실무 성취 표현의 결정판입니다.`},{id:`d6-t4`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`What a relief! Let's call it a day right at five today. Do you have any big plans for the weekend?`,slashBroken:`What a relief! / Let's call it a day right at five today. / Do you have any big plans / for the weekend?`,korean:`정말 다행이다! 오늘은 딱 5시에 칼퇴하자. 이번 주말엔 무슨 특별한 계획 있어?`,keyHighlight:`call it a day / have any big plans`,noteKo:`Day 1(call it a day)과 Day 3(have plans)가 금요일 퇴근 스몰토크로 자연스럽게 이어집니다.`},{id:`d6-t5`,speaker:`Marcus`,roleLabel:`디자인 리드`,voicePitch:.92,sceneImage:`assets/scene_cafe_detour.jpg`,cameraMotion:`pan-right`,english:`First, I'm going to stop by that bakery on my way home and treat myself to an almond croissant.`,slashBroken:`First, I'm going to stop by that bakery / on my way home / and treat myself to an almond croissant.`,korean:`일단 퇴근길에 그 빵집에 잠깐 들러서 고생한 나한테 아몬드 크루아상을 선물할 거야.`,keyHighlight:`stop by ~ on my way home / treat myself to`,noteKo:`Day 1 동선 구동사(stop by ~ on my way home)에 treat myself to를 얹어 생생하게 답합니다.`},{id:`d6-t6`,speaker:`Chloe`,roleLabel:`프로덕트 매니저`,voicePitch:1.08,sceneImage:`assets/scene_riverside_walk.jpg`,cameraMotion:`pan-left`,english:`Love that! Tomorrow morning I'm definitely sleeping in, and then going for a river walk to clear my head.`,slashBroken:`Love that! / Tomorrow morning I'm definitely sleeping in, / and then going for a river walk / to clear my head.`,korean:`너무 좋다! 난 내일 아침엔 무조건 푹 늦잠 자고, 저녁엔 머리도 식힐 겸 강변 산책을 나갈 거야.`,keyHighlight:`sleeping in / going for a river walk / clear my head`,noteKo:`주말 꿀잠(sleep in)과 Day 5 힐링 루틴(clear my head)의 결합!`},{id:`d6-t7`,speaker:`Marcus`,roleLabel:`디자인 리드`,voicePitch:.92,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Enjoy your well-deserved weekend, Chloe! Keep me posted if you find any good cafes along the river.`,slashBroken:`Enjoy your well-deserved weekend, Chloe! / Keep me posted / if you find any good cafes along the river.`,korean:`고생 많았으니 꿀주말 보내, 클로이! 강변에 좋은 카페 발견하면 소식 알려주고!`,keyHighlight:`well-deserved weekend / Keep me posted`,noteKo:`주말 인사의 정석 "Enjoy your well-deserved weekend!"로 Week 1 시트콤 스토리가 막을 내립니다.`}],grammarSections:[{title:`Week 1 총정리 ① · 한국인이 가장 자주 틀리는 전치사 & 부사 5대 함정 체크리스트`,coreFormula:`on my way home (to 금지) | by Friday (완료) vs until Friday (지속) | discuss + 목적어 (about 금지)`,wrongKonglish:`On my way to home, let us discuss about the report until Friday.`,rightNative:`On my way home, let's discuss the report so we can wrap it up by Friday.`,explanationKo:`이번 주에 교정한 핵심 어법 포인트입니다. ① 부사 home/back 앞 to 삭제, ② in my way(방해) vs on my way(동선), ③ on time(정각) vs in time(늦지 않게), ④ 완료 마감 by vs 지속 until, ⑤ 타동사 discuss 뒤 about 삭제 — 이 5가지는 종합 모의고사 단골 출제 포인트입니다.`,registerSpectrum:{casual:`I'm on my way home—I'll text you by 8!`,standard:`Let's discuss the timeline so we stay on track by Friday.`,formal:`Please submit your feedback by EOD Wednesday; our office remains open until 6 PM.`}},{title:`Week 1 총정리 ② · 콩글리시 명사·동사를 원어민 구동사·연어로 치환하기`,coreFormula:`many works → swamped with work | promise → plans | ambiguous → tight | healing → unwind/recharge`,wrongKonglish:`My schedule is ambiguous because of many works and a friend promise.`,rightNative:`My schedule is tight since I'm swamped with work and already have dinner plans.`,explanationKo:`한국어 단어를 1:1 사전식으로 번역하면 어색한 콩글리시가 됩니다. 상황의 본질 그림을 떠올려 구동사(stop by, drop off, pick up, ended up -ing, push back, wrap up, clear my head)로 바꾸는 순간 문장이 짧고 강력해집니다.`,registerSpectrum:{casual:`I'm swamped today—rain check on dinner?`,standard:`Tomorrow looks tight on my end, so could we push it back?`,formal:`Due to a prior commitment, may we reschedule our session for Thursday?`}},{title:`Week 1 총정리 ③ · 구동사 대명사 위치 & 동명사 결합 절대 법칙`,coreFormula:`pick it up / drop them off / push it back / wrap it up & end up V-ing / make a habit of V-ing`,wrongKonglish:`I ended up to pick up it late.`,rightNative:`I ended up picking it up late.`,explanationKo:`문장 뼈대를 세운 뒤 정확도를 100점으로 끌어올리는 마지막 디테일입니다. ① 타동사+부사 구동사에 대명사(it/them)가 오면 반드시 가운데에 끼워 넣고(picking it up), ② end up과 전치사(of, for, instead of) 뒤 동사는 반드시 -ing 형태로 연결하세요.`,registerSpectrum:{casual:`Don’t worry, I’ll lock it in right now!`,standard:`We ended up wrapping it up ahead of schedule.`,formal:`We have made a habit of double-checking all figures prior to sign-off.`}}],sprintDrills:[{id:`d6-s01`,drillType:`chunk-build`,promptKo:`[종합 1] 퇴근길에 세탁물을 찾아가려고 잠깐 들렀어요.`,promptEnHint:`Day 1 핵심: stopped by + on my way home + to pick up`,targetEn:`I stopped by on my way home to pick up my laundry.`,chunks:[`I stopped by`,`on my way home`,`to pick up`,`my laundry.`],explanationKo:`home 앞 무전치사와 stop by / pick up 구동사 콤보입니다.`},{id:`d6-s02`,drillType:`active-blank`,promptKo:`[종합 2] 일찍 자려 했는데 결국 밤을 꼬박 새우게 됐어요.`,promptEnHint:`Day 2 핵심: ended up 뒤에 pull을 알맞게 변형하세요.`,targetEn:`I meant to sleep early, but I ended up pulling an all-nighter.`,blankData:{before:`I meant to sleep early, but I ended up`,answer:`pulling`,after:`an all-nighter.`,firstLetterHint:`p______ (-ing 형태)`},explanationKo:`end up + 동명사(-ing) 규칙에 따라 pulling an all-nighter가 됩니다.`},{id:`d6-s03`,drillType:`konglish-fix`,promptKo:`[종합 3] "수요일은 제 쪽 일정이 좀 애매한데 목요일은 괜찮으실까요?"`,promptEnHint:`Day 3 핵심: tight on my end + work instead`,targetEn:`Wednesday looks tight on my end—would Thursday work instead?`,wrongKonglishOption:`Wednesday is ambiguous to me—would Thursday possible instead?`,explanationKo:`tight on my end와 조동사 Would 뒤 동사원형 work 결합을 확인하세요.`},{id:`d6-s04`,drillType:`active-blank`,promptKo:`[종합 4] 금요일 퇴근 전까지 최종안을 마무리해서 공유드릴게요.`,promptEnHint:`Day 4 핵심: 마감 완료 시점 전치사(2글자)`,targetEn:`I'll wrap up the final draft by EOD Friday and keep you in the loop.`,blankData:{before:`I'll wrap up the final draft`,answer:`by`,after:`EOD Friday and keep you in the loop.`,firstLetterHint:`b_ (2글자)`},explanationKo:`완료 데드라인 앞에는 전치사 by를 사용합니다.`},{id:`d6-s05`,drillType:`chunk-build`,promptKo:`[종합 5] 제가 가장 좋아하는 점은 저녁 산책이 복잡한 머리를 식혀준다는 거예요.`,promptEnHint:`Day 5 핵심: What I love most is that ~`,targetEn:`What I love most is that evening walks clear my head.`,chunks:[`What I love most`,`is that`,`evening walks`,`clear my head.`],explanationKo:`복수 주어 evening walks에 맞춰 that절 동사는 clear를 씁니다.`},{id:`d6-s06`,drillType:`konglish-fix`,promptKo:`[종합 6] "이번 주 토요일 아침엔 알람 안 맞추고 푹 늦잠 잘 거예요!"`,promptEnHint:`실수로 지각 잠(oversleep) vs 휴일 꿀늦잠(sleep in)을 구별하세요!`,targetEn:`I'm going to sleep in this Saturday morning!`,wrongKonglishOption:`I'm going to oversleep intentionally this Saturday morning!`,explanationKo:`휴일에 기분 좋게 일부러 늦잠 자는 것은 구동사 sleep in을 씁니다.`},{id:`d6-s07`,drillType:`chunk-build`,promptKo:`[종합 7] 화요일에 늦게까지 남아 일했던 노력이 정말 빛을 발했어요!`,promptEnHint:`Day 6 핵심: 보람이 있다/결실을 맺다 paid off`,targetEn:`Working late on Tuesday really paid off!`,chunks:[`Working late`,`on Tuesday`,`really`,`paid off!`],explanationKo:`동명사 주어 Working late on Tuesday + really paid off 구조입니다.`},{id:`d6-s08`,drillType:`active-blank`,promptKo:`[종합 8] 이렇게 급하게(촉박하게) 통화를 요청드려 죄송합니다.`,promptEnHint:`on _____ notice (갑작스러운 통보에)`,targetEn:`Sorry to ask for a call on such short notice.`,blankData:{before:`Sorry to ask for a call on such`,answer:`short`,after:`notice.`,firstLetterHint:`s____ (5글자)`},explanationKo:`on short notice는 실무에서 급한 요청을 할 때 필수 매너 표현입니다.`},{id:`d6-s09`,drillType:`chunk-build`,promptKo:`[종합 9] 예정된 일정보다 이틀 앞서서 프로젝트를 마무리했어요.`,promptEnHint:`ahead of schedule을 문장 끝에 배치하세요.`,targetEn:`We wrapped up the project two days ahead of schedule.`,chunks:[`We wrapped up`,`the project`,`two days`,`ahead of schedule.`],explanationKo:`ahead of schedule(일정보다 앞서) ↔ behind schedule(일정보다 늦어).`},{id:`d6-s10`,drillType:`konglish-fix`,promptKo:`[종합 10] "제가 그것을 내일까지 마무리해서 맡기고 갈게요." (대명사 어순 주의!)`,promptEnHint:`구동사 두 개(wrap up, drop off) 모두 대명사 it의 위치를 확인하세요.`,targetEn:`I'll wrap it up and drop it off by tomorrow.`,wrongKonglishOption:`I'll wrap up it and drop off it until tomorrow.`,explanationKo:`wrap it up + drop it off + by tomorrow — Week 1 핵심 어법 3가지의 완결판입니다!`}],worksheetExam:[{id:`d6-ex01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 1 동선 구동사`,questionKo:`빈칸에 알맞은 구동사(과거형 2단어)를 넣어 "퇴근길에 꽃집에 잠깐 들렀다"를 완성하세요.`,stimulusEn:`I __________ __________ the flower shop on my way home.`,answer:`stopped by`,acceptableAlt:[`swung by`],explanationKo:`동선 중 잠깐 들르다는 stop by(과거형 stopped by)를 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "출근길에 세탁물을 맡기고 갔다" 빈칸(과거형 2단어)을 채우세요.`,stimulusEn:`I __________ __________ my laundry on my way to work.`,answer:`dropped off`,explanationKo:`drop의 과거형은 p를 한 번 더 써서 dropped off가 됩니다.`}},{id:`d6-ex02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 2 의도 vs 결과`,questionKo:`괄호 안 동사 order를 알맞게 변형하여 "결국 자정에 치킨을 시키게 됐다"를 완성하세요.`,stimulusEn:`I meant to skip supper, but I ended up __________ (order) fried chicken at midnight.`,answer:`ordering`,explanationKo:`end up 뒤에는 동명사(-ing)가 와야 하므로 ordering이 정답입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "급한 일이 갑자기 생겼다"가 되도록 빈칸 구동사(과거형 2단어)를 쓰세요.`,stimulusEn:`Something urgent __________ __________ right before the meeting.`,answer:`came up`,explanationKo:`예기치 않은 이슈 발생은 came up입니다.`}},{id:`d6-ex03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 3 일정 조율`,questionKo:`빈칸에 알맞은 구동사(2단어)를 넣어 "회의를 오후 4시로 뒤로 미루다"를 완성하세요.`,stimulusEn:`Could we __________ __________ our sync to 4 PM?`,answer:`push back`,explanationKo:`회의 시간을 늦출 때는 push back을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 반대로 회의를 오전 10시로 "앞당기다"(2단어)를 쓰세요.`,stimulusEn:`Can we __________ __________ the call to 10 AM?`,answer:`move up`,explanationKo:`일정을 앞당기는 것은 move up입니다.`}},{id:`d6-ex04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 4 마감과 승인`,questionKo:`빈칸에 알맞은 구동사(3단어)를 넣어 "부사장님이 예산안을 최종 승인하셔야 한다"를 완성하세요.`,stimulusEn:`Our VP needs to __________ __________ __________ the budget by Friday.`,answer:`sign off on`,explanationKo:`공식 결재·최종 승인은 sign off on으로 표현합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "진행 상황을 계속 공유드리겠습니다" 빈칸(3단어)을 채우세요.`,stimulusEn:`I'll keep you __________ __________ __________.`,answer:`in the loop`,explanationKo:`keep someone in the loop 관용구입니다.`}},{id:`d6-ex05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 5 피로 해소`,questionKo:`빈칸에 알맞은 단어(1단어)를 넣어 "하루의 긴장을 풀고 쉬다"를 완성하세요.`,stimulusEn:`Taking a warm shower helps me __________ after a hectic day.`,answer:`unwind`,acceptableAlt:[`relax`],explanationKo:`긴장을 풀며 쉬다는 뜻의 핵심 동사 unwind입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "복잡한 머리를 식히다" 빈칸(2단어)을 채우세요.`,stimulusEn:`Evening walks always help me __________ my __________.`,answer:`clear head`,explanationKo:`clear my head 연어입니다.`}},{id:`d6-ex06`,number:6,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 6 실무 숙어`,questionKo:`빈칸에 알맞은 전치사구(3단어)를 넣어 "갑작스러운(촉박한) 연락에도 도와주셔서 감사하다"를 완성하세요.`,stimulusEn:`Thank you so much for helping us out __________ __________ __________.`,answer:`on short notice`,explanationKo:`사전 예고 시간이 거의 없이 급하게 요청했을 때 on short notice를 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "우리의 노력이 마침내 결실을 맺었다!" (과거형 2단어)`,stimulusEn:`All our hard work finally __________ __________!`,answer:`paid off`,explanationKo:`pay off의 과거형 paid off입니다.`}},{id:`d6-ex07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`전치사 종합 판별`,questionKo:`다음 네 문장 중 전치사 쓰임이 **완벽하게 올바른** 문장은?`,stimulusEn:`Day 1~5에서 다룬 전치사 규칙을 모두 적용해 판별하세요.`,options:[`I picked up coffee on my way to home.`,`Please submit the final deck until EOD Friday.`,`Let’s discuss the bottleneck by tomorrow noon.`,`My eyes hurt from staring to my phone screen.`],answer:`Let’s discuss the bottleneck by tomorrow noon.`,explanationKo:`① home 앞 to 삭제, ② 완료 제출이므로 by EOD Friday, ④ stare at my phone screen이어야 합니다. ③번만 타동사 discuss(무전치사) + by tomorrow noon으로 완벽합니다!`,twinClinic:{questionKo:`[쌍둥이 클리닉] "월요일까지 쭉 휴가 중이다"에 알맞은 전치사(1단어)를 쓰세요.`,stimulusEn:`He will be on vacation __________ Monday.`,answer:`until`,explanationKo:`휴가 상태의 지속이므로 until을 씁니다.`}},{id:`d6-ex08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`sleep in vs oversleep 구별`,questionKo:`빈칸 (A)와 (B)에 들어갈 동사가 문맥에 맞게 짝지어진 것은?`,stimulusEn:`(A) Since tomorrow is a holiday, I plan to __________ until 11 AM!
(B) Oh no, my alarm didn’t go off, so I __________ and missed the bus.`,options:[`(A) sleep in — (B) overslept`,`(A) oversleep — (B) slept in`,`(A) stay in — (B) locked in`,`(A) head out — (B) came up`],answer:`(A) sleep in — (B) overslept`,explanationKo:`휴일에 의도적으로 푹 늦잠 자는 건 sleep in, 알람을 못 듣고 실수로 늦잠 자 지각한 건 overslept입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "일요일 아침에 늦잠 자는 걸 정말 좋아해요" 빈칸(2단어)을 쓰세요.`,stimulusEn:`I love to __________ __________ on Sunday mornings.`,answer:`sleep in`,explanationKo:`기분 좋은 휴일 늦잠은 sleep in입니다.`}},{id:`d6-ex09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`구동사 대명사 어순 종합`,questionKo:`다음 중 어법상 **틀린** 문장을 고르세요.`,stimulusEn:`구동사와 대명사 목적어의 결합 위치를 확인하세요.`,options:[`Once the draft is ready, I'll wrap it up.`,`Could we push it back by an hour?`,`Let’s lock in it right away.`,`I dropped them off at the lobby.`],answer:`Let’s lock in it right away.`,explanationKo:`타동사+부사 구동사 lock in의 목적어가 대명사 it일 때는 반드시 Let’s lock it in으로 가운데에 넣어야 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 위 틀린 부분을 바른 3단어로 고쳐 쓰세요.`,stimulusEn:`Let's __________ __________ __________ right away.`,answer:`lock it in`,explanationKo:`lock it in이 올바른 어순입니다.`}},{id:`d6-ex10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`콩글리시 명사 총정리`,questionKo:`다음 한국어 뜻과 자연스러운 영어 표현의 연결이 **잘못된** 것은?`,stimulusEn:`Week 1 핵심 콩글리시 교정 노트 점검`,options:[`친구와 저녁 약속이 있다 → I have dinner plans with a friend.`,`내일 일정이 좀 애매하다 → Tomorrow looks a bit tight on my end.`,`요즘 업무량이 너무 많다 → I have too many works lately.`,`산책하며 힐링했다 → Going for a walk helped me unwind and recharge.`],answer:`요즘 업무량이 너무 많다 → I have too many works lately.`,explanationKo:`업무(work)는 불가산 명사이므로 too much work, a heavy workload, 또는 swamped with work로 써야 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "업무에 파묻혀 정신없이 바쁘다" (be ________ with work) 1단어를 쓰세요.`,stimulusEn:`I've been __________ with work lately.`,answer:`swamped`,explanationKo:`be swamped with work 연어입니다.`}},{id:`d6-ex11`,number:11,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`일정 진척도 표현`,questionKo:`예정했던 마감일보다 **사흘이나 더 일찍** 개발을 끝냈을 때 쓰는 표현은?`,stimulusEn:`The engineering team finished the build three days ____________________.`,options:[`ahead of schedule`,`behind schedule`,`in my way`,`out of the loop`],answer:`ahead of schedule`,explanationKo:`예정보다 앞서 조기 완료했을 때는 ahead of schedule을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 반대로 예정보다 "일정이 뒤처져/밀려 있다"는 2단어 표현은?`,stimulusEn:`We are running slightly __________ __________.`,answer:`behind schedule`,explanationKo:`behind schedule로 지연 상태를 표현합니다.`}},{id:`d6-ex12`,number:12,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`비즈니스 쿠션 응답`,questionKo:`회의 중 아직 확인되지 않은 데이터 질문을 받았을 때 가장 프로페셔널한 대처 문장은?`,stimulusEn:`즉답을 피하면서도 신뢰감을 주는 표현을 고르세요.`,options:[`I have no idea, don't ask me now.`,`Let me double-check the numbers and circle back to you by EOD.`,`My data is ambiguous, please wait until forever.`,`Let’s call it a day and forget the numbers.`],answer:`Let me double-check the numbers and circle back to you by EOD.`,explanationKo:`[재확인 약속(double-check) + 회신 약속(circle back) + 명확한 기한(by EOD)] 3박자를 모두 갖춘 모범 비즈니스 답변입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "일정을 재확인해보고 정오까지 연락드릴게요"에서 회신 구동사(3단어)를 넣으세요.`,stimulusEn:`Let me check my calendar and __________ __________ __________ you by noon.`,answer:`get back to`,explanationKo:`get back to someone은 circle back to와 함께 가장 많이 쓰입니다.`}},{id:`d6-ex13`,number:13,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`나 자신에게 보상하기`,questionKo:`힘든 프로젝트를 끝낸 금요일 밤, "고생한 나 자신에게 맛있는 초밥을 대접할 거야"에 가장 알맞은 표현은?`,stimulusEn:`After wrapping up the launch, I'm going to ____________________ some great sushi.`,options:[`treat myself to`,`drop myself off`,`pencil myself in`,`loop myself on`],answer:`treat myself to`,explanationKo:`treat oneself to [명사]는 스스로에게 특별한 선물이나 맛있는 음식을 대접한다는 뜻입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "충분히 누릴 자격이 있는 꿀휴식"을 뜻하는 하이픈 형용사(1단어)는?`,stimulusEn:`Have a __________ break this weekend!`,answer:`well-deserved`,explanationKo:`well-deserved break / weekend로 고생한 동료를 격려합니다.`}},{id:`d6-ex14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 1+4 결합 서술형`,questionKo:`주어진 청크를 배열하여 완전한 문장을 작성하세요.`,stimulusEn:`[ by 5 PM / and stop by / I will wrap this up / on my way home. / the bookstore ]`,answer:`I will wrap this up by 5 PM and stop by the bookstore on my way home.`,explanationKo:`[업무 마감] I will wrap this up by 5 PM + [퇴근 동선] and stop by the bookstore on my way home.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "정오까지 그것을 마무리해서 당신 자리에 맡기고 갈게요." (I will wrap it up / by noon / and drop it off / at your desk.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I will wrap it up by noon and drop it off at your desk.`,explanationKo:`wrap it up과 drop it off의 대명사 어순을 정확히 지킵니다.`}},{id:`d6-ex15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 2 의도·결과 서술형`,questionKo:`주어진 청크를 올바른 순서로 배열하여 문장을 완성하세요.`,stimulusEn:`[ came up / on time, / I meant to leave / and I ended up / working late. / but something urgent ]`,answer:`I meant to leave on time, but something urgent came up and I ended up working late.`,explanationKo:`Day 2의 핵심 3요소(meant to V / something urgent came up / ended up V-ing)를 한 문장으로 엮은 마스터 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "집에서 쉬려 했는데 결국 친구들과 저녁을 먹으러 나갔어요." (I meant to stay in, / but I ended up / going out for dinner / with friends.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I meant to stay in, but I ended up going out for dinner with friends.`,explanationKo:`stay in(집콕)과 going out(외출)의 대조가 선명합니다.`}},{id:`d6-ex16`,number:16,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 3 일정 역제안 서술형`,questionKo:`우리말 뜻에 맞게 정중한 비즈니스 일정 조율 문장을 작성하세요.`,stimulusEn:`우리말: 내일 오전은 제 쪽 일정이 좀 빠듯하네요. 대신 금요일 오후 2시는 괜찮으실까요?
(힌트: Tomorrow morning looks a bit tight on my end. / Would Friday at 2 PM work instead?)`,answer:`Tomorrow morning looks a bit tight on my end. Would Friday at 2 PM work instead?`,explanationKo:`쿠션 거절 문장과 Would ~ work instead? 역제안 문장의 완벽한 2문장 세트입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "오늘 점심은 다음을 기약해도 될까요?" (Can I / take a rain check / on lunch / today?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Can I take a rain check on lunch today?`,explanationKo:`take a rain check on ~ 구문입니다.`}},{id:`d6-ex17`,number:17,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 4 선제 공유 서술형`,questionKo:`주어진 청크를 배열하여 원격 협업 미팅 마무리 문장을 완성하세요.`,stimulusEn:`[ signs off on / Once our director / in the loop. / the plan, / I will keep everyone ]`,answer:`Once our director signs off on the plan, I will keep everyone in the loop.`,explanationKo:`부사절 현재시제(signs off on)와 주절 미래시제(will keep ~ in the loop)를 정확히 맞춥니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "남은 사소한 버그 몇 가지만 출시 전에 매끄럽게 해결하면 됩니다." (We just need to / iron out / a few minor bugs / before launch.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`We just need to iron out a few minor bugs before launch.`,explanationKo:`세부 문제를 해결하다는 iron out을 활용합니다.`}},{id:`d6-ex18`,number:18,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 5 강조 구문 서술형`,questionKo:`주어진 청크를 배열하여 취미의 매력을 설명하는 문장을 완성하세요.`,stimulusEn:`[ work stress / What I love most / takes my mind off / is that it / about running / and clears my head. ]`,answer:`What I love most about running is that it takes my mind off work stress and clears my head.`,explanationKo:`What절 강조 주어 + takes my mind off + clears my head까지 스피킹 핵심 표현이 응축되어 있습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "화요일에 야근했던 것이 정말 보람이 있었어요!" (Working late / on Tuesday / really paid off!)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Working late on Tuesday really paid off!`,explanationKo:`노력이 결실을 맺었다는 칭찬·회고 표현입니다.`}},{id:`d6-ex19`,number:19,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`종합 콩글리시 클리닉`,questionKo:`다음 문장에 숨어 있는 **3가지 오류**(urgent something, ended up to, until Friday)를 모두 바르게 고쳐 쓰세요.`,stimulusEn:`오류 문장: Urgent something came up, so we ended up to push the launch back until Friday.`,answer:`Something urgent came up, so we ended up pushing the launch back to Friday.`,acceptableAlt:[`Something urgent came up, so we ended up pushing the launch back by Friday.`],explanationKo:`① Something urgent (후치 수식), ② ended up pushing (동명사), ③ push ~ back to Friday (새로운 일정 시점 전치사 to).`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: On my way to home, I checked your mail. (오류 2곳 교정)`,stimulusEn:`바른 문장 전체를 작성하세요.`,answer:`On my way home, I checked your email.`,explanationKo:`home 앞 to 삭제, mail → email로 고칩니다.`}},{id:`d6-ex20`,number:20,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Week 1 파이널 영작`,questionKo:`Week 1 마지막 문제입니다! 다음 우리말을 배운 표현들을 조합해 자연스러운 영어로 완성하세요.`,stimulusEn:`우리말: 이번 주 금요일에 커피 한잔 가볍게 하면서 밀린 이야기 나누자!
(힌트: Let’s / grab a coffee / this Friday / and catch up!)`,answer:`Let's grab a coffee this Friday and catch up!`,acceptableAlt:[`Let's grab coffee this Friday and catch up!`,`Let's grab a coffee this Friday and catch up.`],explanationKo:`축하합니다! grab a coffee와 catch up을 결합해 언제든 동료·외국인 친구에게 먼저 말 걸 수 있는 완벽한 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "고생 많으셨으니 자격 충분한 꿀주말 보내세요!" (Enjoy / your well-deserved / weekend!)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Enjoy your well-deserved weekend!`,explanationKo:`Week 1 완주를 진심으로 축하드립니다!`}}],tutorScenario:{openingQuestionEn:`Happy Friday! Looking back on this week, how did your work or study go, and how are you planning to treat yourself and unwind this weekend?`,openingQuestionKo:`해피 프라이데이! 이번 한 주를 돌아보면 업무나 공부는 어땠나요? 그리고 이번 주말엔 고생한 나 자신에게 어떤 휴식이나 보상을 선물하실 계획인가요?`,followUpQuestionEn:"You've earned a well-deserved break! Which expression from Week 1 (`stop by`, `ended up -ing`, `tight on my end`, `wrap up by`, `clear my head`) do you think you'll use first in real life?",followUpQuestionKo:`정말 푹 쉬실 자격이 충분하네요! 이번 주 배운 핵심 표현 중 실제 생활이나 업무에서 가장 먼저 써보고 싶은 표현은 무엇인가요?`,recommendedChunks:[`meant to ~, but ended up -ing`,`wrapped up ~ by Friday`,`stop by ~ on my way home`,`treat myself to ~`,`clear my head`],modelAnswerEn:`It was quite a hectic week, and I ended up working late on Wednesday, but we wrapped everything up on track by Friday! Tonight I'm going to stop by my favorite bakery on my way home to treat myself, and tomorrow I'll sleep in and go for a walk to clear my head.`}},s=[t,n,r,i,a,o];export{s as WEEK1_MODULES};